/* =========================================================================
   Bordeaux Dashboard — wat de châteaux zelf schreven, in het Nederlands
   -------------------------------------------------------------------------
   Dezelfde sleutels en dezelfde velden als in fiches.js: note is wat het
   seizoen deed, taste is de degustatienotitie.

   Waar het château in het Frans publiceerde, is uit het Frans vertaald en
   niet uit het Engels van fiches.js — zo staat er één vertaling tussen de
   wijnboer en de lezer in plaats van twee. Waar het château zelf in het
   Engels publiceerde, is dat Engels het origineel.

   Wat hier ontbreekt, valt in de app terug op het Engels.
   ========================================================================= */

window.BDX_FICHES_NL = {
'figeac|2021':{window:'Anders dan in het verleden zijn zelfs de zeer jonge jaargangen een genoegen om te drinken.'},
'dauzac|2003':{window:'Mond: zeer goed in balans, fluweelachtige tannine, een elegante wijn om vanaf nu en nog vijf tot zes jaar te drinken.'},
'batailley|2019':{window:'Rokerige tonen kenmerken de aromatische retour en wijzen op een opmerkelijk bewaarpotentieel.'},
'domaine-de-chevalier|1995':{decant:'Een uur voor het proeven karafferen (voor de beluchting).'},'batailley|2000':{taste:'Donkere robijnrode kleur. Zeer bloemig bouquet met tonen van cassis. De aanzet in de mond is breed; de vanille van de houtopvoeding is aanwezig zonder het rode fruit te verbergen. Schitterende lengte in de mond.'},
'batailley|2003':{taste:'Mooie granaatrode robe. Bouquet van cassis, vanille, tabak en zoethout. Aanzet met veel fruit, een breed, rond lichaam, typisch voor deze jaargang, met zeer rijpe tannine die het diepe grindterroir van Pauillac uitdrukt. Een goed uitgebalanceerde wijn met mooie lengte.'},
'batailley|2005':{taste:'De robe is diep robijnrood met granaatrode reflexen. De neus is zeer rijk, met intense tonen van gekonfijt zwart fruit. De aanzet in de mond is zuiver, het lichaam krachtig, rond en goed gestructureerd. De afdronk is breed en rust op zeer aanwezige tannine.'},
'batailley|2006':{taste:'Donker robijnrode robe. Mooi, fruitig bouquet van kersen en rode en zwarte bessen, met aroma’s van leer, hout, tabak en grafiet. In de mond kenmerkt Château Batailley 2006 zich door zijn fraaie fluweligheid, zijn kruidige structuur, zijdeachtige tannine en goede zuurgraad, met tonen van rood fruit.'},
'batailley|2008':{taste:'Donker robijnrode robe. Bouquet van ceder, tabak, specerijen en kersen. In de mond is deze wijn vlezig, met goede structuur, een fluwelen textuur en tonen van cassis, leer, specerijen en grafiet. Klassiek van stijl is Château Batailley 2008 een elegante wijn.'},
'batailley|2009':{taste:'Schitterende diepe rode kleur. De aroma’s doen denken aan rood fruit en cassis, met kruidige en subtiel houtgerijpte tonen. In de mond toont hij zich rond, vlezig en van elegante finesse. Mooie lengte, met een charmante afdronk en tonen van leer.'},
'batailley|2011':{taste:'Mooie purperen robe. Aangename, expressieve neus met fruitige aroma’s (pruim, cassis), hout en specerijen. Een vlezige wijn, soepel en zacht, met mooie rijkdom en kruidige tonen. Mooie lengte in de afdronk.'},
'batailley|2012':{taste:'Purperen robe. Fraaie neus met aroma’s van bosbes, cassis, koffie en leer, met een lichte kruidige toets. In de mond een zeldzame rijkdom met zachte tannine. Een frisse wijn, krachtig en goed in balans.'},
'batailley|2013':{taste:'De robe is granaatrood en de neus fraai kruidig. De mond is fris en elegant, middelzwaar, met mooie tonen van zoethout en leer. Een kruidige, fraaie afdronk. Een mooi geslaagd geheel.'},
'batailley|2015':{taste:'Diepe, intense robe. Fruitige neus met aroma’s van verse braam en framboos en enkele minerale tonen. Een rode wijn die geconcentreerd is in aroma en goed in balans in de mond. Een Pauillac die nog tot zeven jaar kelder verdient voordat hij gedronken wordt.'},
'batailley|2017':{taste:'De neus ontwikkelt aroma’s van rood fruit, die doorlopen in de mond, waar ze zich verbinden met tonen van koffie en vanille; de frisheid van deze wijn eindigt in een zeer lange afdronk met tonen van grafiet.'},
'batailley|2022':{taste:'Met een donkere robe ontwikkelt hij een intens bouquet van zwart fruit en zoete specerijen, onderstreept door geroosterde, empyreumatische tonen. Zeer rasecht is de mond compact en teder, getekend door een stevig aanwezige tanninestructuur en een romige afdronk. De persistentie is opmerkelijk, op tonen van vers fruit.'},
'branaire-ducru|2005':{window:'Bewaren: 20 jaar.',decant:'Een karaf van minstens een uur zal de aromatische expressie van Branaire-Ducru 2005 ten goede komen.',note:'Het klimatologische feit van 2005 blijft de droogte: een neerslagtekort van 40% ten opzichte van normaal, van november 2004 tot eind augustus 2005. 2005 was een tamelijk warm jaar, maar zonder hittegolf: de temperatuursommen liggen onder die van 2003, boven die van 2002 en 2004, en gelijk aan die van 2000.'},
'branaire-ducru|2006':{decant:'Een karaf van minstens een uur zal de aromatische expressie van Branaire-Ducru 2006 ten goede komen.',note:'2006 begon met een zeer natte winter. De eerste tien dagen van september zijn schitterend: droog weer en hoge temperaturen (30 °C in de namiddag) versnellen de rijping van de druiven.',taste:'De regen van de week ervoor heeft de druiven ongetwijfeld licht getekend, maar hun aanvankelijke concentratie houdt een zeer hoog niveau vast: fruit, materie en fijnheid van de tannine, en een zuurgraad die het geheel een mooie levendigheid geeft. De cabernets en petit verdots zijn diep van kleur en rijk, met mooie tannine en een fraaie zuiverheid en complexiteit van aroma’s.'},
'branaire-ducru|2007':{decant:'Een karaf van minstens een uur zal de aromatische expressie van Branaire-Ducru 2007 ten goede komen.',note:'Omlijst door twee uitzonderlijk gunstige periodes was de zomer niet zo zonnig als we gewenst hadden. Zeer droog en zonnig weer en noord- tot noordoostenwind maakten een perfect einde van de rijping mogelijk.',taste:'Het was eerder de frequentie dan de uiteindelijk vrij geringe hoeveelheden die de periode tekenden. De druiven rijpen langzaam, wat hun een mooie rijpheid en een fraaie aromatische frisheid geeft, met tannine die zeer geleidelijk maar tot in de diepte is verfijnd.'},
'branaire-ducru|2008':{decant:'Een karaf van minstens een uur zal de aromatische expressie van Branaire-Ducru 2008 ten goede komen.',note:'2008 begon met een koele, natte lente. De bloei in Saint-Julien verloopt onder gunstige omstandigheden: de gemiddelde bruto-opbrengst op het domein is 44 hl/ha, iets lager dan die van vorig jaar.',taste:'Het fruit rijpt langzaam, maar het schitterende naseizoen laat de aroma’s en de tannine tot in de diepte verfijnen.'},
'branaire-ducru|2009':{decant:'Een karaf van minstens een uur zal de aromatische expressie van Branaire-Ducru 2009 ten goede komen.',note:'Na een koude winter en een koud begin van de lente komt de wijnstok in 2009 vrij laat op gang. De bloei verloopt goed en garandeert bevredigende opbrengsten van 47 hl/ha voor het hele domein.',taste:'De neus ontwikkelt rijp fruit dat tegelijk fris en kruidig is, van mooie precisie en grote finesse. De mond is rijk, dicht en zacht, zeer fluwelig en met een mooie aromatische lengte.'},
'branaire-ducru|2010':{decant:'Een karaf van minstens een uur zal de aromatische expressie van Branaire-Ducru 2010 ten goede komen.',note:'In de lente van 2010 leiden temperaturen die iets koeler zijn dan gemiddeld tot een betrekkelijk late uitloop. De koele nachten bevorderen echter, ondanks een uitgesproken droogte, een goed waterherstel van de stokken, wat gunstig is voor de fotosynthese.',taste:'Tegelijk scherpt de koelte van de herfsttemperaturen de definitie van de aroma’s aan, behoudt ze de zuurgraad en laat ze de tannine langzaam en grondig rijpen.'},
'branaire-ducru|2011':{window:'2011 komt ons voor als een zeer serieuze wijn met een mooi bewaarpotentieel.',decant:'Een karaf van minstens een uur zal de aromatische expressie van Branaire-Ducru 2011 ten goede komen.',note:'De uitzonderlijk warme lente van 2011 bracht een zeer vroege start van de wijnstok op gang; ze was ook uitzonderlijk droog. De herfst, warmer dan normaal en met een aanhoudend watertekort, liet de druiven onder goede omstandigheden rijpen.',taste:'De rijke, expressieve neus mengt zwart fruit met bloemige tonen van grote finesse. De mond is dicht en mooi levendig, en de tannine die hem draagt is van grote precisie.'},
'branaire-ducru|2012':{decant:'Een karaf van minstens een uur zal de aromatische expressie van Branaire-Ducru 2012 ten goede komen.',note:'2012 begint met een droge en bijzonder koude winter. De eveneens koele lente zorgt voor een vrij late uitloop van de wijnstok (rond 10 april).',taste:'In de neus ontwikkelt zich een grote complexiteit, die op expressieve wijze frisheid en mooie rijpheid, mineraliteit en de rijkdom van een langzaam en volmaakt gerijpt fruit samenbrengt. De aanzet toont een mooie dichtheid van tannine met een delicate toets.'},
'branaire-ducru|2013':{decant:'Een karaf van minstens een uur zal de aromatische expressie van Branaire-Ducru 2013 ten goede komen.',note:'2013 begint met een koele lente; het begin van de ontwikkeling van de wijnstok is laat en traag. De herfst is natter, met meer regendagen dan normaal, al blijft de totale neerslag onder de seizoensnormalen.',taste:'De mond is in balans, op mooi gul vlees met elegante tannine. Na omstandigheden die lastiger waren dan gewoonlijk zijn wij uiteindelijk trots op en tevreden met de kwaliteit van deze jaargang.'},
'branaire-ducru|2014':{note:'Na een uitzonderlijk zachte winter loopt de wijnstok bijna vijftien dagen vóór op het tienjarig gemiddelde uit. De lente is nat en tamelijk koel; de bloei profiteert begin juni van goede temperaturen.',taste:'Gestructureerd en zacht met verfijnde tannine ontwikkelt de wijn zich zeer smaakvol, rijk van smaak, en wint hij aan kracht naar een geparfumeerde en lange afdronk.'},
'branaire-ducru|2015':{note:'Zeer aromatische neus, fijn, fruitig en rijp, met de bramengelei-toets van de jaargang. Deze omstandigheden samen waren gunstig voor de tannine-opbouw in de schillen, de ontwikkeling van de pitten en de afbraak van groene aroma’s; vanaf eind juli liet regen een gelijkmatige en snelle véraison toe.',taste:'Geconcentreerde tannine ontmoet een naadloze lijn van sappige cassis in de mond. De structuur is stevig en strak, en eindigt met een opwaartse zweem zuren.'},
'branaire-ducru|2016':{note:'De lente is nat en koel, maar laat mooie bladoppervlakken en een fraai vegetatief evenwicht van de wijnstok ontstaan. Een mooie periode droog en zonnig weer aan het eind van de eerste tien dagen van juni is gunstig voor een zeer mooie bloei op de meeste van onze percelen.'},
'branaire-ducru|2017':{note:'Terwijl het begin van de winter, tot eind januari, zeer koud is, is de tweede helft bijzonder zacht. Daarna versterkt de bijzonder warme en droge lente het vroege karakter van de jaargang.',taste:'De mond heeft meteen présence, met fijne, zijdeachtige tannine. Die frisheid geeft een mooie lift aan de verbluffend lange afdronk.'},
'branaire-ducru|2018':{note:'In de winter van 2017 en de lente van 2018 viel veel regen, waardoor het grondwaterpeil op een goed niveau kwam. De lente was warm en de bloei verliep onder goede omstandigheden.',taste:'De zeer expressieve neus biedt een mooie complexiteit van goed rijp fruit, goed in balans gehouden door frissere tonen.'},
'branaire-ducru|2019':{note:'Met een zacht einde van de winter is de uitloop van de wijnstok vroeg en gelijkmatig. In de lente is het weer koel en vochtig en groeit de stok traag.'},
'branaire-ducru|2020':{note:'De lente is eveneens zacht en nat, zeer gunstig voor de meeldauw, die bijzondere aandacht vraagt.'},
'branaire-ducru|2021':{note:'2021 begint met een zeer zachte en bijzonder natte winter. De lente is zeer koel en nat: de bloei loopt vertraging op.',taste:'De druiven toonden een schitterende concentratie en een schitterende verfijning van de tannine.'},
'branaire-ducru|2022':{window:'Het resultaat is een wijn die ik nu wil drinken, en de komende paar decennia!',taste:'Bij het proeven toont Branaire-Ducru 2022 een diepe kleur. De neus is zeer expressief, complex, rijk aan zwart fruit van mooie rijpheid, maar zonder enige zwaarte.'},
'branaire-ducru|2023':{window:'Dit is een wijn die behoorlijk goed zal verouderen, en toch heerlijk zal drinken na maar een paar jaar rijping.',note:'De winter, rijk aan regen, laat de waterreserves van de bodem zich goed herstellen, wat nuttig is voor de verdere ontwikkeling van de wijnstok. De bloei verloopt goed en de vruchtbaarheid van de knoppen is hoog.',taste:'Aan het begin van de opvoeding biedt de wijn een zeer expressieve neus van goed rijp fruit, gecombineerd met kruidiger tonen en fraaie toetsen frisheid. De aanzet in de mond is zeer rond en ontwikkelt zich op soepele, gesmolten tannine. De afdronk is persistent en zeer elegant.'},
'cantemerle|2025':{note:'De eerste oogst in het pas gerenoveerde gistlokaal is met de grootst mogelijke zorg voor de druif binnengehaald.',taste:'De neus is intens, gedomineerd door knapperig fruit en opgetild door een delicate bloemige toets. De mond bevestigt die mooie belofte: tegelijk teder en krachtig rekt de materie zich uit.'},
'clerc-milon|1995':{taste:'De wijn heeft een mooi, donker granaatrood dat aan de rand licht begint te verkleuren, terwijl de neus, nog vol jeugd, lagen van gebrande koffie en zoethout ontvouwt voordat hij zuivere aroma’s van gestoofd fruit en braam ontwikkelt. In de mond maakt een precieze, geciseleerde aanzet plaats voor dicht geweven, stijlvolle tannine, nog altijd jeugdig. De smaken in de mond herinneren aan de aroma’s van de neus.'},
'clerc-milon|1996':{taste:'De wijn is diep rood en begint heel licht te verkleuren. De intense eerste neus opent op zwarte kers en rode bes met enkele bloemige tonen. Met lucht wordt hij complexer en onthult hij achtereenvolgens tonen van grafiet, koude rook en tegen het einde een vleugje zoethout. De aanzet is soepel, de structuur verfijnd en elegant, met een mooi evenwicht tussen een kwieke, verfrissende zuurgraad en sappig fruit.'},
'clerc-milon|1997':{taste:'De wijn is dicht van kleur, met een lichte baksteentint, terwijl de bijzonder complexe neus geuren van verwelkte bloemen, wierook en tabak prijsgeeft, vermengd met vluchtiger aroma’s van braam en humus. Zoetheid in de mond gaat samen met goed afgeronde tannine. De fijn uitgebalanceerde, soepele structuur en de combinatie van rokerige tonen met bosbessenfruit laten zien dat deze Clerc Milon nu volledig rijp is.'},
'clerc-milon|1998':{taste:'Een zeer dicht, donker granaatrood; de kleur is geëvolueerd zoals te verwachten was. Aanvankelijk ingetogen opent de neus zich met lucht en onthult hij warme aroma’s van zwarte kers, humus en delicaat hout op tonen van vanille en sigarenkistje. Een soepele aanzet baant de weg voor krachtige, volledig rijpe tannine. De mond, stevig en verkwikkend, is goed in balans en loopt uit op een frisse, minerale afdronk.'},
'clerc-milon|1999':{taste:'De wijn heeft een diepe, heldere kleur met een lichte baksteentint en een krachtige, rijke neus die opent op een reeks aroma’s, van specerijen en gedroogde bloemen tot rood fruit en leer, om vervolgens preciezere tonen van geroosterd brood en amandel te ontwikkelen. De aanzet, zowel vol als soepel, maakt plaats voor een rijke tanninestructuur, gedragen door wildtonen en sigarenkistje.'},
'clerc-milon|2000':{taste:'Een zeer diep en dicht purper; de wijn heeft een krachtige en elegante neus op weelderige aroma’s van in alcohol gemacereerd zwart fruit, met tonen van munt en kamfer, tabak en mokka. De aanzet is meteen smeuïg en zacht, de textuur zeer dicht, met robuuste, voorwaartse tannine. Hij blijft aangenaam hangen in de mond, gedragen door de gemacereerde zwartekersentonen van de neus.'},
'clerc-milon|2001':{taste:'Een diep en glanzend granaatrood; de wijn heeft een zeer verfijnde neus die aroma’s van grafiet, nootmuskaat, vanille en gedroogde bloemen ontwikkelt. Vanuit een soepele en fraai dichte aanzet bouwt hij op stevige, goed geïntegreerde tannine, die een rijk, zacht lichaam draagt met sappige zoethouttonen. De elegante, volle afdronk eindigt op een vleugje specerij.'},
'clerc-milon|2002':{taste:'Een diep en intens granaatrood dat weinig tekenen van ouderdom toont; de wijn heeft een precieze en intense neus, met lucht gedomineerd door sappige aroma’s van verse tabak, humus, witte peper, koude rook en mokka. De volle aanzet brengt een toets fruit en een zweem zoetheid in de mond, die vervolgens opbouwt op een krachtige, stevige tanninestructuur, gedragen door een aangename frisheid.'},
'clerc-milon|2003':{taste:'De wijn heeft een diepe, glanzende kleur die aan de rand naar baksteen neigt, en een zonnige, intense, licht muntige neus die opent op aroma’s van amandel, gekonfijte kweepeer, gebrande koffie en zoethout. In de mond maakt hij meteen indruk met zijn zoetheid, kracht en dichtheid, en toont hij volmaakt rijpe en nog wat voorwaartse tannine. De smaken herinneren aan de aroma’s van de neus, met volrijp fruit en koffie.'},
'clerc-milon|2004':{taste:'Een nog jeugdig donkerpurper; de wijn heeft een fijn opgebouwde neus die frisse, precieze aroma’s van cassis en zwarte kers ontwikkelt, vermengd met sandelhout en grafiet. Vanuit een precieze, ronde aanzet biedt de mond aangename substantie, een fijne textuur en harmonieuze tannine, opgetild door voorwaarts en knapperig zwart fruit. De lange, verrukkelijke afdronk toont een mooi evenwicht.'},
'clerc-milon|2005':{taste:'De wijn heeft een diepe kleur met een violette zweem. De neus opent op aangename rokerige tonen, gevolgd door intense, krachtige aroma’s van rijp besfruit, vooral cassis en bosaardbei. Vol en breed in de mond toont hij dicht geweven tannine en een reeks gulle, gevarieerde smaken: braam, kers, specerijen en zoethout. De brede, goed uitgebalanceerde afdronk verenigt stevigheid met definitie.'},
'clerc-milon|2006':{taste:'De wijn, een geconcentreerd donkerrood van aanzienlijke intensiteit, heeft een zeer verfijnde neus die opent op licht geroosterde aroma’s vermengd met bloemige tonen. In de mond onthult hij een strak geweven structuur van stijlvolle tannine, dicht maar niet hard, versterkt door voorwaarts fruit met knapperige kersentonen. De lange, smaakvolle afdronk is mooi in balans en drukt de frisheid van het fruit uit.'},
'clerc-milon|2007':{taste:'De wijn heeft een zeer diepe purperen kleur met een lichte violette zweem en een geconcentreerde, compacte neus die opent op aroma’s van garrigue, cassis en cederhout, begeleid door fijne tonen van vanille en toast. De mond is vol, op licht melkige smaken van rood fruit, gedragen door soepele, dicht geweven tannine. Een fraaie frisheid begeleidt een lange, goed uitgebalanceerde afdronk.'},
'clerc-milon|2008':{taste:'De wijn is zeer dicht rood. De neus, die het hoge aandeel Merlot weerspiegelt, opent op intense, haast jamachtige aroma’s van rood fruit, vermengd met watertandende tonen van vanille en gebrande koffie. Krachtig en vol in de mond is dit een volmaakt gestructureerde wijn met jong, knapperig fruit. Een voorwaartse frisheid geeft de tanninestructuur grote verve en draagt bij aan het evenwicht van het geheel.'},
'clerc-milon|2009':{taste:'Een intens purper met violette zweem; Clerc Milon 2009 toont een krachtige, warme neus van zwart fruit vermengd met minerale tonen, zoethout, viooltje en anijs. De aanzet is vol en precies. De romige streling van de structuur komt meteen naar voren, met knapperige, overvloedige tannine van zeer precieze textuur. Rijpe fruitsmaken vullen de mond en herinneren aan de neus.'},
'clerc-milon|2010':{taste:'De wijn is zeer diep rood met een violette zweem. Overrijp zwart fruit, specerijen, pure chocolade en oranjebloesem vermengen zich harmonieus in de zeer krachtige en complexe neus. Vanuit een rechtlijnige, volle aanzet rondt de mond zich zacht af op sappig vers fruit en zoethout. De fluwelen textuur omsluit de tanninestructuur en zorgt voor evenwicht en grote verfijning.'},
'clerc-milon|2011':{taste:'De wijn is diep en stralend granaatrood. De neus geeft fijn geroosterde tonen van specerijen en tabak prijs, gecombineerd met intensere aroma’s van rood fruit en kersenpit, met een minerale toets. De mond is vol en goed afgetekend, beheerst door de glans van sappig fruit en verfijnde, smaakvolle tannine die opent op een zweem chocolade. De lange, warmhartige afdronk wordt opgetild door een licht ziltige toon.'},
'clerc-milon|2012':{taste:'De wijn heeft een dieper roodpurper. De concentratie in de neus komt met grote verfijning en complexiteit naar voren. Aroma’s van zwarte kers en vanille maken plaats voor diepere, rokerige, turfachtige tonen met blonde tabak en gedroogde bloemen. Verfijning is overal in de mond: de weelderige, romige aanzet breidt zich uit over goed geïntegreerde tannine en mengt zich met gulle, gevarieerde smaken die aan morel doen denken.'},
'clerc-milon|2013':{taste:'Een intens granaatrood; de wijn is helder en glanzend. In de neus toont Clerc Milon 2013 stralende aroma’s van licht jamachtige framboos met bloemige en minerale tonen. Complex en innemend worden die aroma’s versterkt door elegant en fijn geroosterd hout. Vanaf de aanzet toont de mond de precieze persoonlijkheid van de wijn, met rondheid en heldere definitie.'},
'clerc-milon|2014':{taste:'De kleur is diep granaatrood met een purperen zweem. De verfijnde, elegante neus toont volmaakt rijp fruit, terwijl zwemen grafiet en zoethout samen met aromatische verbena-tonen een indruk van sappige frisheid achterlaten. Vanuit een zeer volle aanzet bouwen de smaken naar een rijk en harmonieus evenwicht. De tannine is goed afgerond, zijdeachtig en romig, en draagt de expressie van kruidig, oordeelkundig hout.'},
'clerc-milon|2015':{taste:'De wijn is kristalhelder granaatrood met violette reflexen. De frisse, elegante neus wasemt rijpe morel uit, gevolgd door subtiele tonen van zoethout en toast, wat een rijk en complex maar licht en luchtig bouquet oplevert. Aanvankelijk verfijnd en zijdeachtig wint de mond aan kracht op fijn geciseleerde tannine, omhuld door knapperige smaken van rood fruit, pure chocolade en gedroogde bloemen.'},
'clerc-milon|2016':{taste:'De wijn heeft een zeer diepe, haast zwarte kleur met een glanzende tint. De verfijnde, elegante neus onthult intense aroma’s van rijp fruit, vermengd met tonen van zoethout en peper. Een brede, precieze aanzet luidt een dicht en romig mondgevoel in, dat een gul en goed uitgebalanceerd smaakpalet biedt. De middenmond bekleedt de mond met braam en bosbes, met fijne tannine en expressief, kruidig hout.'},
'clerc-milon|2017':{taste:'Een rijke kleur met granaatrode tint. De neus opent op braamtonen, vermengd met verfijnde zwemen gebrande koffiebonen. Met lucht ronden nobele, delicate tonen van grafiet, vuursteen en cacao dit zeer aantrekkelijke aromapalet af. Een frisse, volle aanzet laat een indruk van gulheid en schitterend evenwicht achter, en leidt naar een middenmond op kersenpit en pure chocolade, gedragen door geciseleerde tannine.'},
'clerc-milon|2018':{taste:'De wijn heeft een diepe kleur met een karmozijnrode tint. De brede, sappige neus opent op aroma’s van verse bessen zoals cassis, met tonen van viooltje. Met lucht komen tonen van specerijen en zoethout op, die herinneren aan de rijpheid van de druiven, met daartegenover toetsen munt. De dichte, weelderige aanzet leidt naar een frisse, zachte middenmond, gedragen door gulle, zijdeachtige tannine, met peper en pure chocolade.'},
'clerc-milon|2019':{taste:'De wijn is karmozijngetint granaatrood. Elegant en verfijnd wasemt de neus bloemige aroma’s uit en ontwikkelt hij met lucht tonen van cassis en zoethoutwortel. De volle, zachte aanzet onthult een verleidelijk en complex smaakpalet waarin rijp fruit schitterend wordt afgezet tegen tonen van geroosterde granen en viooltje. De middenmond wordt gedragen door hoogwaardige, dicht geweven en romige tannine.'},
'clerc-milon|2020':{taste:'De wijn is diep kersrood met granaatrode reflexen. De neus onthult een intens en complex aromapalet waarin gemacereerd zwart fruit zich mengt met zoethout en cederhout. Bij de aanzet verenigt het romige, zijdeachtige mondgevoel diepte, dichtheid en opperste elegantie, en leidt het naar een rijke, zachte middenmond op cassis en bosbes, verlicht door een fraaie frisheid over een ronde, verfijnde tanninestructuur.'},
'clerc-milon|2021':{taste:'De wijn is diep rood met granaatrode tint. De voorname, elegante neus drukt aroma’s van kers, cassis en zoethout uit, vermengd met bloemige tonen van viooltje. De rijke, krachtige aanzet onthult een precieze en elegante tanninestructuur in de middenmond. Verfijnde toetsen peper en cederhout ronden een stralend smaakpalet af. De prachtig uitgebalanceerde afdronk blijft lang hangen en kondigt uitstekende rijping aan.'},
'clerc-milon|2022':{taste:'Château Clerc Milon 2022 belichaamt de intensiteit en de concentratie van de jaargang. Tonen van bosbes en ander wild besfruit, begeleid door specerijen, peper en een vleugje viooltje, komen samen in een rijk en complex geheel. De frisheid van zoethout en minerale tonen is volmaakt in balans met de beheerste kracht van zijdeachtige, goed geïntegreerde tannine, wat alle elegantie en precisie van deze zeer fijne wijn toont.'},
'clerc-milon|2023':{taste:'Diep rood met granaatrode tint; de wijn toont verfijnde, elegante aroma’s van bosbes en cassis, begeleid door subtiele zwemen cederhout en peper. Romige zachtheid en precisie worden gedragen door goed gestructureerde, stijlvolle tannine, die grote complexiteit meegeeft. De dichte, volle textuur die groot Cabernet Sauvignon eigen is, wordt opgetild door een fraaie uitbarsting van fruit. De frisheid blijft hangen in de afdronk.'},
'clerc-milon|2024':{taste:'Een diep en intens rood; de wijn heeft een precieze en subtiele neus die een complex aromapalet onthult waarin tonen van bosbes en framboos worden versterkt door toetsen van zachte specerijen, cederhout, mokka en chocolade. Prachtig in balans is de textuur zowel zacht als verfijnd, terwijl de stralende mond een elegante structuur biedt met zeer verfijnde tannine van uitzonderlijke zuiverheid.'},
'cos-labory|2025':{taste:'De wijn toont zich toegankelijk zonder simpel te zijn, van grote zuiverheid met stralend fruit, een belofte van plezier al in zijn jeugd.'},
'coutet|2010':{note:'De oogst wordt met de hand binnengehaald, in kleine kistjes, op rijpheid. Na een terugkeer van de kou in mei zonder neerslag verloopt de bloei begin juni onder goede omstandigheden, mede dankzij een opwarming.'},
'coutet|2011':{note:'De oogst wordt met de hand binnengehaald, in kleine kistjes, op rijpheid. Een droge lente dwong de wijnstok dieper te putten uit de klei-kalkhoudende ondergrond.'},
'coutet|2012':{note:'De oogst wordt met de hand binnengehaald, in kleine kistjes, op rijpheid. Het begin van 2012 kenmerkt zich door grillig weer, met een natte lente waarin koelte en vocht elkaar afwisselen tot begin juli.'},
'coutet|2013':{note:'2013 werd getekend door een lente waarin koelte en vocht elkaar afwisselden tot begin juli, wat de uitloop van de wijnstok enigszins vertraagde.'},
'coutet|2014':{note:'Voor deze nieuwe jaargang noteerden wij een uitzonderlijk natte en zachte winter, die de waterreserves van de bodem aanvulde en een vroege uitloop van de wijnstok op gang bracht (ongeveer tien dagen vóór).'},
'coutet|2015':{note:'2015 is een van de droogste en zonnigste jaren in vijftig jaar.'},
'coutet|2016':{note:'De zeer natte lente bood de bloei een luwte die lang genoeg duurde om zich onder goede omstandigheden te voltrekken.'},
'coutet|2017':{note:'Een lichte witte vorst op de ochtend van 21 april trof minder dan 10% van onze wijngaard. Op 27 april werd echter zware schade vastgesteld, na drie opeenvolgende nachten zwarte vorst.',taste:'Lichte, bleke robe. De neus, van grote complexiteit, biedt tonen van citrus (limoen, gekonfijte citroen), gember en abrikoos, maar ook witte bloemen. In de mond is de aanzet mooi levendig, met een opmerkelijke aromatische frisheid. Het knapperige, gulle karakter wordt onderstreept door citrus en sinaasappelessence.'},
'coutet|2018':{note:'De lente van 2018 was bijzonder nat: bijna 200 mm regen viel in de anderhalve maand tussen eind april en half juni. Augustus en september, extreem droog, voltooiden de rijping van de bessen, maar veroorzaakten een zeer late ontwikkeling van de botrytis.',taste:'Strokleurige robe. De neus toont fraaie tonen van bittere sinaasappel, pompelmoes, verse gember en witte perzik. Met lucht komen bloemige toetsen van jasmijn en acacia. De aanzet is soepel, fris en levendig. Het geheel heeft een mooie dichtheid met een fluwelige, smeuïge kant, geheel in finesse. De wijn kenmerkt zich door een aangename levendigheid en een opmerkelijk evenwicht.'},
'coutet|2019':{note:'Een natte lente: na een maart dicht bij normaal brachten april en mei veel neerslag, wat de wijnstok goed liet ontwikkelen en de bloei begin juni onder goede omstandigheden liet beginnen. Een droge, hete zomer: het begin van de zomer werd getekend door een vroege hittegolf met recordtemperaturen.',taste:'De jaargang 2019 brengt de karakteristieke neus van Coutet naar voren, getekend door tonen van gember, peer en exotisch fruit. De mond is dit jaar bijzonder fris en geeft een Coutet van zeer moderne stijl.'},
'coutet|2020':{note:'Eind maart bracht vorst, die gelukkig verscheidene nachten met vuren in toom werd gehouden. De lente was zacht en nat, wat de wijnstok krachtig deed groeien.',taste:'2020 is een uitermate fijne jaargang. De eerste degustaties van Coutet laten een bijzonder frisse wijn zien, getekend door bloemige tonen van lelietje-van-dalen en pompelmoesbloesem. De levendigheid in de mond is typisch voor de terroirs van Château Coutet in Barsac.'},
'coutet|2021':{note:'Na een bijzonder koud begin van de winter, waarin vijftien dagen met temperaturen onder nul werden gemeten, zette droog weer in tot het begin van de lente. Slechts enkele percelen bleven, plaatselijk, gespaard van die voorjaarsvorst; de oogst was al zwaar getroffen.',taste:'Zeer luchtige neus met overheersende bloemige tonen: verbena, citroengras en acaciabloesem. Frisse mond met een aanwezige zoetheid, die zich ontwikkelt op tonen van acaciahoning. De afdronk ontwikkelt aroma’s van limoen en gekarameliseerde citroen. Een zeer minerale wijn, luchtig en delicaat.'},
'coutet|2022':{note:'Na een koude winter, vooral in januari met zeventien dagen onder nul, was het begin van de lente zacht, maar van 3 tot 5 april volgde een late vorstperiode tijdens de uitloop van de wijnstok, gelukkig zonder gevolgen voor de komende oogst.',taste:'De neus is getekend door gekonfijte aroma’s van kweepeer en vijg, geroosterde en vanilletonen, maar ook frissere zoals gember, gekonfijte citroen en lemon curd. In de mond heeft de wijn meteen een zeer krachtige aanzet van opmerkelijke complexiteit. De frisheid houdt de kracht en het vet van deze zeer evenwichtige wijn in balans.'},
'coutet|2023':{note:'De winter was zeer zacht, nog uitgesprokener dan het jaar ervoor, ondanks een koudere februari. Tijdens het groeiseizoen lag de neerslag 10% onder het gemiddelde van de laatste dertig jaar, met een tekort dat opliep tot 25% als juni buiten beschouwing blijft.',taste:'De neus toont aroma’s van mango en geroosterde ananas, met nuances van kweepeer en gekonfijte citroen, opgetild door een subtiele bloemige toets. In de mond toont de wijn zich soepel en in balans, met delicate exotische tonen en een aangename frisheid. De zachte, harmonieuze afdronk rekt zich uit op accenten van gekonfijte citrus en een lichte kruidige punt.'},
'coutet|2024':{note:'Na een zachtere winter dan normaal met recordneerslag verliep de uitloop van de wijnstok tussen 21 en 27 maart, enkele dagen vóór het gemiddelde.'},
'coutet|2025':{note:'Na een winter die dicht bij de normalen van de laatste jaren lag, zowel qua temperatuur als qua neerslag, verliep de uitloop onder goede omstandigheden, van 1 tot 7 april.'},
'darmailhac|1992':{taste:'Aantrekkelijk en donker van kleur, met een baksteentint. De neus opent langzaam en suggereert aroma’s van zwart fruit en humus, met een kruidige toets die aan zoethout doet denken. De aanzet is rond en onthult een verfijnde tanninestructuur zonder scherpe kanten, met expressieve smaken van leer en sigarenkistje. In de afdronk komen rokerige tonen op, met een fraaie herinnering aan het fruit.'},
'darmailhac|1993':{taste:'Een aantrekkelijk donkerrood met baksteentint. De neus is delicaat maar intens, op tonen van specerijen, cederhout en kruidnagel. De aanzet toont aangenaam geïntegreerde tannine, terwijl de middenmond doet denken aan zwart fruit: kers en cassis. In de harmonieuze, aanhoudende afdronk komen muntige smaken op.'},
'darmailhac|1995':{taste:'De wijn heeft een mooie, diepe kleur en een rechtlijnige neus die nog aroma’s van besfruit behoudt, vooral cassis, maar al zeer aangename sporen toont van meer ontwikkelde tonen: vanille, karamel, gebrande koffie en hout. In de mond geven voorwaartse maar zachte tannine volume en karakter, en omsluiten ze elegant rijke smaken, opbouwend naar een complete afdronk, krachtig en gul, typisch voor de jaargang.'},
'darmailhac|2001':{taste:'Een diepe, intense kleur met een licht baksteenachtige zweem. Aanvankelijk ingetogen opent de neus zich en onthult hij uiteenlopende aroma’s van rood fruit en humus, met enkele subtiele biscuit- en toasttonen. Goed gestructureerd in de mond mengt de expressieve tannine zich met een veelheid aan smaken van rood fruit en specerijen. De lange, smaakvolle afdronk speelt meer op verfijning dan op kracht.'},
'darmailhac|2003':{taste:'De wijn heeft een aantrekkelijke, rechtlijnige rode kleur en een verfijnde, fruitige neus waarin kers zich mengt met viooltje en tabak. Rond in de mond, met veel lichaam en gewicht, wikkelt hij zijn al zijdeachtige tannine om een reeks sappige smaken (rood fruit, karamel, zoethout, menthol, gebrande koffie) tot een rijk aromatisch geheel. De afdronk barst van het fruit.'},
'darmailhac|2005':{taste:'De wijn heeft een aantrekkelijke kleur, donker en diep. De neus combineert op delicate wijze bloemige aroma’s, besfruit (braam en kers), vers fruit dat aan nectarine doet denken, en een toets gebrande koffie. Breed en stevig in de mond toont hij voorwaartse maar al goed geïntegreerde tannine die een indruk van lichaam en gewicht geeft, aangenaam gedragen door verfijnd, geroosterd en licht rokerig hout.'},
'darmailhac|2008':{taste:'Diep rood; Château d’Armailhac 2008 is een wijn in de klassieke vorm. De neus toont fruitige aroma’s van morel, opgetild door delicate toetsen gebrande koffie en vanille. Vanuit een rechtlijnige, elegante aanzet ontwikkelt de mond smaken van rood fruit, gedragen door zeer elegante, zijdeachtige tannine. Rond en vol biedt de wijn een lange, aanhoudende afdronk.'},
'darmailhac|2014':{taste:'De kleur is diep en dicht. De zeer verfijnde neus wasemt aroma’s van wilde braamlikeur en kers uit, afgerond door subtiele tonen van zoethout en specerijen. De aanzet toont een mooi evenwicht en de tannine is goed gestructureerd, omhuld door een rijk en zacht lichaam met jamachtige fruitsmaken. De afdronk toont een wijn vol belofte, met een eerste vaart van het fruit die hem uitstekende lengte geeft.'},
'darmailhac|2018':{taste:'De wijn heeft een diepe kleur met granaatrode tint. De rijke, compacte neus opent op aroma’s van braam en marsepein. Met lucht wordt het eerste fruit aangevuld met een reeks tonen van specerijen en pure chocolade. De krachtige, goed gestructureerde aanzet onthult peperige en licht muntige smaken, en leidt naar een middenmond gedragen door elegante, dichte tannine op gebrande koffieboon en zoethout.'},
'darmailhac|2021':{taste:'De wijn is glanzend robijnrood. De verfijnde, elegante neus toont aroma’s van rode bes en framboos, gecombineerd met tonen van brioche en viooltje. Bij de aanzet komt sappig, mondvullend fruit tevoorschijn onder ronde, goed geïntegreerde tannine. De mond, fraai in balans gehouden door een frisse, minerale structuur, onthult delicate chocoladetonen omhuld door een zachte, zijdeachtige textuur.'},
'darmailhac|2022':{taste:'Château d’Armailhac 2022 is de belichaming van beheerste kracht. Hij toont alle dichtheid van de jaargang, afgezet tegen grote frisheid en opmerkelijke lengte, en biedt een raamwerk van smaken van zwart fruit vermengd met chocolade, peper en specerijen, en een bloemige toets die te danken is aan de uitzonderlijke Cabernet Franc van het domein, die in deze jaargang al zijn elegantie toont.'},
'darmailhac|2023':{taste:'Een donker en intens rood met karmozijnen tint; de wijn geeft aroma’s van rood fruit prijs, begeleid door lichte, subtiele bloemige tonen en delicate toetsen snoepgoed die harmonieus samengaan met zwarte kers. Zacht en precies toont hij verfijnde, elegante tannine met frisheid en een mooi evenwicht. Die indruk houdt aan, met aangename tonen van specerijen en peper, gevolgd door rijp fruit dat lang nazindert.'},
'darmailhac|2024':{taste:'Robijnrood met karmozijnen tint; de wijn onthult een fraai intense neus, beheerst door tonen van bosbes en framboos, begeleid door subtiele aroma’s van cassisknop en een vleugje pepermunt. Een algehele indruk van harmonie wordt versterkt door een gevoel van frisheid, terwijl aroma’s van rood fruit zich vermengen met een delicaat weefsel van bloemige tonen. Verkwikkend en kaarsrecht toont hij heldere energie in de mond.'},
'dauzac|2000':{note:'In het Zuidwesten in het algemeen en in de Bordeaux in het bijzonder zal de jaargang 2000 bij de wijnboeren in het geheugen blijven om een uitgesmeerde oogst, tussen 20 september en 13 oktober.',taste:'Uiterlijk: diep van kleur, een diep rood met baksteenachtige nuances. Neus: geroosterde tonen van broodkorst en mokka, met aroma’s van onderhout, paddenstoelen en gestoofde pruimen. Mond: zeer geconcentreerd, zeer rijp, met ronde, volle tannine.'},
'dauzac|2004':{window:'Te drinken van nu tot tien jaar, of langer voor wie rijpe wijnen graag heeft.',note:'Deze jaargang volgt op 2003, die getekend werd door een kleine oogst als gevolg van droogte en zeer hoge zomertemperaturen.',taste:'Rijkdom aan tannine en oneindige soepelheid maken van deze wijn een voortreffelijk raadsel. Er beginnen vleiende evolutie-aroma’s door te komen, zoals pruim.'},
'dauzac|2005':{note:'Van de winter tot de herfst was het klimaat uitzonderlijk droog voor de streek.',taste:'Uiterlijk: intens, diep robijnrood, haast zwart. Neus: een neus van uitzonderlijke kracht, die de ervaren André Lurton bekoorde. Een neus sterk gericht op zwart fruit, zwarte kers en cassis.'},
'dauzac|2006':{taste:'Uiterlijk: een schitterende bloedrode robe, diep en donker met granaatrode reflexen. Neus: zeer fruitige aroma’s (bosbes, cassis, braam), onderstreept door aanhoudende geroosterde, empyreumatische tonen (tabak, rook, toast, zoethout). Ook leer is aanwezig. Mond: de rijkdom in de mond is opmerkelijk en verenigt soepelheid met concentratie. De tannine is dicht en bijzonder strak.'},
'dauzac|2007':{note:'2007 was koel en nat van mei tot augustus.',taste:'Uiterlijk: in het glas is de wijn donker en diep. Neus: in 2007 toont Dauzac de volle reikwijdte van zijn aromatische palet.'},
'dauzac|2008':{window:'Gul van fruit — rijp fruit, rood en zwart — met zoethout, kamfer, grillrook en specerijen die uit het glas barsten: een brede, gulle 2008 om vijftien jaar lang te drinken.',note:'Vochtigheid en koelte zouden het klimaat van deze jaargang kunnen kenmerken.',taste:'Château Dauzac 2008 rechtvaardigt ook dit jaar zijn rang als Cru Classé van de Médoc. Geconcentreerd en elegant haalt hij het beste uit zijn uitzonderlijke terroir.'},
'dauzac|2010':{taste:'Uiterlijk: dankzij de inspanningen van zijn team past de wijn van Dauzac vandaag volmaakt in de typiciteit van Margaux. De jaargang 2010 toont een diepe, dichte robijnrode robe. Neus: het nu al gulle en krachtige bouquet van mokka en bosvruchten loopt vanaf de eerste slok door in heerlijke smaken.'},
'dauzac|2011':{taste:'Uiterlijk: zeer diep purper, in de lijn van de grote wijnen die Château Dauzac de laatste jaren heeft gemaakt. Neus: de kracht van zijn aroma’s valt meteen op, rijk aan beloften. Dauzac komt vandaag dicht bij de koplopers van de appellatie, en de dichtheid van deze jaargang zal hem over vier of vijf jaar volop in het licht zetten, na de eerste fase van de houtopvoeding.'},
'dauzac|2012':{note:'Die inspanningen werden met succes bekroond en stelden ons in staat druiven van zeer mooie kwaliteit te oogsten.',taste:'Uiterlijk: een purperen robe met violette reflexen. Neus: een complex bouquet met aroma’s van cassis en mokka. Mond: tonen van zwart fruit keren terug in de mond, met een goede levendigheid die elegante frisheid geeft. In de afdronk aroma’s van zoethout met een lange frisheid, die de kwaliteit van de Cabernet Sauvignon bevestigt. De precieze tannine staat garant voor een mooie evolutie.'},
'dauzac|2014':{note:'Een atypisch klimaat, met een zachte en natte winter en een vroege lente met zachte temperaturen maar koele nachten. Een wonderbaarlijke herfst, droog en warm — de warmste in honderd jaar — maakte concentratie en een uitzonderlijke rijpheid mogelijk.'},
'dauzac|2015':{note:'De hitte van de zomer maakte plaats voor het licht van september, en liet ons de herinnering na aan een zeer gelijkmatige bloei en een droge, gematigde zomer: de belofte van een grote jaargang. De lichte regens van augustus en half september gaven de bladeren hun glans terug en lieten de druiven zich volzuigen met aroma’s, tannine, suikers en anthocyanen.'},
'dauzac|2016':{note:'Een begin van het jaar onder een oceanisch klimaat, gevolgd door een langdurige periode van zon en hitte tot 13 september, toen neerslag de wijnstok zijn rijping liet voltooien. De indian summer van oktober stelde ons in staat de langste oogst uit de geschiedenis van Château Dauzac uit te voeren (21 dagen) en de Merlot en de Cabernet Sauvignon op optimale rijpheid binnen te halen.'},
'dauzac|2017':{note:'Een tamelijk droge en zonnige winter, gevolgd door een zachte maart, bracht de eerste wijnbladeren zeer vroeg. De zware voorjaarsvorst in de Bordeaux eind april spaarde de hele wijngaard van Château Dauzac, waarvan de grindrug dicht bij de rivier ligt.'},
'dauzac|2018':{note:'Een zachte, natte winter liet de wijnstok zich uitstekend ontwikkelen. Na de bloei, die snel en gelijkmatig verliep, sloeg het weer volledig om, met vier maanden zonnige, warme en droge omstandigheden.'},
'dauzac|2019':{note:'Na een winter waarin zachte en koude periodes elkaar afwisselden, was de uitloop tamelijk vroeg. De bloei verliep snel dankzij de zachte temperaturen van eind mei en begin juni.',taste:'Château Dauzac 2019 is een wijn met een uitzonderlijke glans van het fruit. Zeer evenwichtig, met een dichtheid van tannine die een zelden bereikte verfijning en elegantie heeft.'},
'dauzac|2021':{note:'2021 begon met een bijzonder zachte en natte winter. De uitloop was gelijkmatig en vroeg, maar een zeer koude lente deed die voorsprong teniet.'},
'dauzac|2022':{note:'De bijzonder zachte winter bracht een zeer vroege uitloop. Vorst werd vermeden tijdens de koele nachten van april.'},
'dauzac|2023':{note:'Dit jaar was de voorjaarsvorst gering en bleven onze percelen gespaard. De lente, warmer dan gemiddeld, gaf ons een schitterende bloei die eind mei begon.'},
'dauzac|2024':{note:'Na een betrekkelijk zachte winter waren de omstandigheden in de lente over het algemeen gunstig, met een gelijkmatige, vroege bloei die een veelbelovend kwaliteitspotentieel aankondigde. De oogst, die liep van 23 september tot 7 oktober, was optimaal en liet ons volmaakt rijpe druiven plukken, die frisheid verenigen met een intense aromatische expressie.'},
'dauzac|2025':{note:'Na een betrekkelijk zachte winter bood de lente over het geheel genomen gunstige omstandigheden voor de ontwikkeling van de wijnstok, met een gelijkmatige bloei, zij het onderbroken door enkele natte periodes die om verhoogde waakzaamheid in de wijngaard vroegen. De zomer viel uiteen in twee duidelijk onderscheiden delen: een eerste getekend door enige instabiliteit, met afwisselend onweer en aanhoudende vochtigheid.'},
'domaine-de-chevalier|1984':{taste:'Alles aan deze wijn is uitzonderlijk: zijn donkere, ondoorzichtige kleur, zijn aromatische levendigheid, de zich ontvouwende smaak van een overvloedige tannine, robuust maar smaakvol.'},
'domaine-de-chevalier|1989':{taste:'Een grote jaargang, heet en vroeg. Deze wijn smaakte al goed op vat. Donkerrode kleur, met een lichte roodbruine verschuiving aan de rand. Intense en complexe neus: onderhout, leer, verse aarde, rood en zwart fruit. Brede mond, smaakvol en zoet, met een zeer mooi evenwicht. De energie van deze wijn prikkelt de smaakpapillen en versterkt de jeugdige, soepele tannine. Hij heeft nog een groot potentieel. Grote lengte en finesse.'},
'domaine-de-chevalier|1996':{taste:'De wijn geeft het hele ras en de kracht van deze jaargang prijs. De proever blijft daarna hangen in een retronasale indruk die beheerst wordt door rood fruit, zoethout en de zo bijzondere vuursteentoon van onze grindbodems. Het geheel is gesmolten en zacht en toont zijn volle potentieel. Een fles van grote stijl.'},
'domaine-de-chevalier|1998':{decant:'Karafferen aanbevolen (voor de beluchting).',taste:'De uitstekende waterhuishouding van de wijngaard van Chevalier hielp de intense hitte van augustus opvangen en gaf mooie, volle bessen rijk aan tannine. In de neus overheersen aroma’s van gekonfijt rood fruit (braam, kers).'},
'domaine-de-chevalier|1999':{taste:'Donkere kleur, zwart met karmijnrode reflexen. Intense, rechtlijnige neus, fruitig en complex, met minerale, kruidige en balsemieke toetsen. Zoete aanzet, fruitig en glycerinerijk. Zeer subtiel contact in de mond. De mond is breed, redelijk goed gestructureerd en zijdeachtig. Rode bessen zijn aanwezig. Veel charme. De afdronk is verbluffend. De strakke, met fruit omhulde tannine maakt deze wijn zeldzaam elegant.'},
'domaine-de-chevalier|2004':{taste:'Zeer intense donkerrode robe, zwart in het midden. Uitbundige neus van rood en zwart fruit, zoethout en de rokerige kenmerken van het terroir. De minerale en mentholachtige frisheid vergroot de complexiteit.'},
'domaine-de-chevalier|2011':{note:'De jaargang 2011 was vroeg en warm: op een licht natte winter volgde een strenge, hete droogte tot in juli. Een betrekkelijk vochtig en koel klimaat hield aan tot eind augustus — het was lente in de zomer.',taste:'Diepe, donkere en glanzende kleur. Intense en expressieve neus van braam, bosbes en andere complexe tonen van specerijen: peper, vers leer en menthol. In de mond is de finesse evident. Deze wijn is rijk, vlezig, fruitig en geconcentreerd, met grote tannine. Harmonieus en vol delicatesse. Lange afdronk en grote energie, die de kwaliteit en het respect voor het fruit tonen.'},
'domaine-de-chevalier|2015':{taste:'De evenwichten vorderden snel en de oogst leek vroeg te worden, maar we moesten iets wachten om de grote aroma’s van de witte wijnen het best te treffen en de tannine van de rode te verfijnen. Rode oogst: het aanhoudend mooie weer bevorderde een volledige rijpheid van de blauwe rassen, waarvan de tannine zich naar wens verfijnde.'},
'domaine-de-chevalier|2016':{taste:'Grote tannine, omhuld door fruitig vlees, geeft deze textuur die tegelijk zacht en vast is.'},
'giscours|2024':{note:'Na een koele, natte lente onderscheidde de zomer van 2024 zich door het uitblijven van noemenswaardige regen.'},
'giscours|2025':{note:'Na een winter dicht bij de seizoensnormalen en een gunstige lente moest de wijnstok het vanaf de bloei stellen met beperkte waterbeschikbaarheid. De regen van eind augustus, gevolgd door een september met uitzonderlijk koele nachten, liet de rijping geleidelijk en beheerst hervatten, zonder ooit aan concentratie in te boeten.'},
'gruaud-larose|1989':{note:'De vroegheid van de rijping en de rijkdom van de druiven waren uitzonderlijk. Net als de eerste zomermaanden was september heet, zonnig en droog.'},
'gruaud-larose|1990':{note:'Een uitzonderlijk zachte winter, met een extreem hete februari en een zeer vroege, over een langere periode uitgesmeerde uitloop. Eind maart en het grootste deel van april koud, met vorstperiodes (een tweede generatie trossen zag het licht).'},
'gruaud-larose|2019':{taste:'Twee dreigende vorstperiodes in april hebben de wijngaard van Gruaud uiteindelijk nauwelijks geraakt; hij profiteerde van zijn nabijheid tot de Gironde.'},
'gruaud-larose|2022':{note:'Uit een zachte en matig natte winter komend, werden de Merlotpercelen onder aan de ruggen tijdens de eerste tien dagen van april blootgesteld aan een zware vorstperiode.'},
'gruaud-larose|2023':{note:'In de winter worden de bodembedekkers begraasd door een kudde van 300 ooien.'},
'guiraud|2022':{window:'Een zeer lange afdronk, die wijst op het mooie bewaarpotentieel van deze wijn.',note:'Na een zachte winter begon het groeiseizoen van 2022 zeer vroeg.',taste:'Een zeer lange afdronk, die een mooi bewaarpotentieel voor deze wijn aankondigt.'},
'guiraud|2023':{note:'Een over het geheel genomen warme jaargang, met zeer wisselende neerslag. Na een vorstperiode helemaal begin april kwam de groei van de wijnstok op gang onder ideale omstandigheden: warmte en regelmatige regenperiodes brachten een uitbundige vegetatie voort, die alle inzet en vakkennis van onze wijnboeren vroeg om in toom te houden.'},
'haut-bailly|2025':{note:'Een betrekkelijk zachte en natte winter liet allereerst de waterreserves van de bodem zich bevredigend herstellen, een voorwaarde voor een regelmatige watervoorziening van de wijnstok in de zomer. In de lente verliepen de uitloop en de bloei gelijkmatig en bijzonder vroeg.',taste:'De laatste fase van de rijping werd vervolgens ideaal hervat door een weldadige regenbui.'},
'haut-brion|1989':{note:'Een historisch vroeg jaar. De hele groeiperiode door was het weer uitzonderlijk warm, zonnig en droog. De omstandigheden waren dus ideaal voor uitloop, bloei, véraison, rijping en oogst. Een uitzonderlijk jaar kan alleen een uitzonderlijke wijn voortbrengen.',taste:'De wijn is zeer aromatisch en harmonisch, met ongelooflijk gesmolten tannine en tamelijk lage zuren. Je zou denken dat het een krachtige wijn wordt, en toch is hij tegelijk vol subtiliteit en harmonie. Door zijn structuur en zachtheid doet deze wijn aan 1959 denken, zowel wat het weer als wat het volume van de oogst betreft.'},
'haut-brion|1990':{note:'Een warme winter, en dus een uitzonderlijk vroege uitloop. Het begin van de lente was koud, maar de zomer was uitzonderlijk heet en droog. Weinig regen in september maakte een overvloedige en zeer gezonde oogst mogelijk.',taste:'De wijn is niet zo soepel en fluweelachtig als die van \'89. Zijn structuur is eerder die van een klassieke jaargang. Vergelijkbaar met \'88, met de complexiteit, finesse en elegantie die de grote jaren van Haut-Brion kenmerken.'},
'haut-brion|1991':{note:'Een jaar dat in ons geheugen gegraveerd blijft staan als het jaar van de late voorjaarsvorst; een verschrikkelijke vorstperiode verwoestte de wijnstokken in de nacht van 20 april (de kou hield de hele nacht aan en in bepaalde wijngaarden zakte de temperatuur tot -7 °C). De knoppen, die al ver gevorderd waren, werden volledig vernield, en pas eind mei hervatten de wijnstokken hun normale groei.',taste:'Om de ongelijkheid tussen de verschillende ontwikkelingsstadia van de wijnstokken op te vangen — er lag ongeveer vijftien dagen tussen de scheuten die de vorst niet had geraakt en de nieuwe scheuten — moesten we uitzonderlijke maatregelen nemen. Bij het rijpen markeerden we de niet door vorst geraakte scheuten met een bespuiting met Bordeause pap. Die werden afzonderlijk en vóór de andere geoogst.'},
'haut-brion|1992':{note:'Na een droge winter die tot in mei doorliep, was juni zeer vochtig. De bloei duurde lang en verliep ongelijk. Er zat een grote oogst in het vooruitzicht, ondanks coulure (het wegvallen van het stuifmeel) en millerandage (de gebrekkige ontwikkeling van de bessen door slechte bevruchting). Juli en augustus waren zeer heet, met vooral in augustus regen. Dat zorgde voor zorgwekkende sanitaire omstandigheden.',taste:'Een strenge uitdunning op het moment van de rijping. Na uiterste oplettendheid wat de sanitaire toestand betreft, werd bij het plukken opnieuw een bijzonder strenge selectie uitgevoerd. Zo konden we een prachtige en gezonde oogst binnenhalen. De \'92 van Haut-Brion wordt gekenmerkt door de overhand van het fruit. Met zijn goede tannineconcentratie zal hij over een paar jaar aangenaam te drinken zijn.'},
'haut-brion|1993':{note:'Een warme lente bracht een vroege uitloop. Tot in juni was het weer zeer goed. De bloei verliep gelijkmatig. Na een koude periode was augustus tamelijk warm. Augustus maakt de most, zegt een plaatselijk gezegde. De druiven waren opmerkelijk gezond en rijpten goed uit. Het regenachtige weer, met een enkele onweersbui, deed hun niets.',taste:'Onze vervulling en voldoening zijn groot bij deze jaargang. De kleur is diep en gelijkmatig. De neus is typisch Haut-Brion, met het intense aroma van rijpe rode bessen. De tannine is rijk en zacht. De wijn is complex en volmaakt in balans. Het is een buitengewoon goede Haut-Brion.'},
'haut-brion|1994':{note:'Zoals in 1993 wordt deze jaargang gekenmerkt door een vroege rijping, dankzij de zeer zachte winter. Een tamelijk koude en vochtige lente vertraagde de vegetatie enigszins. De zomer was heet, met enkele onweersbuien. De gelijkmatigheid van de bloei was ook bij de rijping te zien. Enige neerslag in september versnelde het plukken van een over het geheel gezonde en goed uitgerijpte oogst.',taste:'Deze wijn wordt gekenmerkt door de harmonie tussen de zeer zachte, zeer fijne structuur en het complexe aroma dat de bodem van de Graves hem geeft. De wijn heeft grote charme. Hij zal de komende jaren te drinken zijn, maar hij verdient het werkelijk om bewaard te worden. Hij zal opmerkelijk goed verouderen.'},
'haut-brion|1995':{note:'1995 was een vroeg jaar. De winter was zacht, de lente heet en droog. Uitloop en bloei waren vroeg en gelijkmatig. Juni, juli en augustus werden gekenmerkt door hoge temperaturen en geen regen. Sommige wijnstokken met oppervlakkige wortels, zoals de jonge aanplant, leden onder de droogte. De oogst was volmaakt rijp en gezond, al was september koeler dan gewoonlijk en regenachtig in het midden van de maand.',taste:'Het kenmerk van deze wijn is de harmonie tussen de zeer zachte, zeer fijne structuur en het complexe aroma dat de aarde van de ‘Graves’ hem geeft. Er zit veel charme in deze fles, die de komende jaren gedronken kan worden of in de kelder bewaard, want de wijn zal opmerkelijk goed verouderen.'},
'haut-brion|1996':{note:'De zomer van 1996 kenmerkte zich vooral door zijn grote onregelmatigheid. Op een paar dagen in juli na waren er geen lange hete periodes. Het begon tamelijk laat in augustus te regenen. De eerste helft van september was gematigd, maar in de tweede helft regende het onophoudelijk. Alles bij elkaar was de zomer middelmatig, met een paar mooie opklaringen.',taste:'Deze jaargang is een wijn vol tegenstrijdigheden en moeilijk te doorgronden. De druiven waren zuur, maar leverden een subtiele wijn. Het suikergehalte was ongewoon hoog, maar de fenolische rijpheid wisselde per ras. De Cabernet Franc en de Cabernet Sauvignon leken rijper dan de Merlots. De kwaliteit lag zeer dicht bij die van de oogst van vorig jaar, maar de structuur van de wijn was anders.'},
'haut-brion|1997':{note:'Een heet, droog begin van het jaar leidde tot een uitzonderlijk vroege groei in de lente. Eind april stonden de wijnstokken ongekend vroeg in bloei. Begin mei stelden buien het einde van de bloei met meer dan een maand uit. De droogte van september zorgde voor een zorgeloze oogst en maakte de ongelijke rijping goed.',taste:'Mooie kleur met tamelijk schitterende, naar oranje tendeerende nuances. De kracht en de complexiteit van de neus verrassen in dit jaar, waarin men zwemen ceder en sigaar vindt naast de andere kenmerken van de jaargang. Een licht aroma van hout omhult eerst het fruit en loopt dan uit op een zweem verse druiven. Een uitstekende aanzet, zacht en soepel tegelijk. Een mooie harmonie voor deze millésime.'},
'haut-brion|1998':{note:'Een zeer regenachtige maand april. Dat kenmerk bleek opmerkelijk nuttig, want mei was droog, juni normaal en juli normaal, grotendeels door twee onweersdagen met zeer zware regen. Augustus was een van de droogste ooit gemeten, en in september begonnen de stortbuien pas na 25 september.',taste:'Zeer klassieke diepe, dichte kleur. Al is hij lichtjes gesloten, de neus geeft een mooie complexiteit en een onmetelijke rijkdom prijs. Het geheel ontwikkelt zich met een duidelijke zachtheid, waarbij een mengeling van de zoetheid en de inktzwarte diepte van een gerijpte port in gedachten komt. Het lichtjes gekarameliseerde rijpe fruit versmelt zijn zweem hout met de duidelijker tonen van geroosterde koffie en cacao. De tannine is voortreffelijk en nog dicht.'},
'haut-brion|1999':{note:'Deze jaargang zal om een aantal buitengewone meteorologische gebeurtenissen in het geheugen blijven. Eerst kwam de zonsverduistering van 11 augustus. Het tweede fenomeen bestond uit twee bijzonder gewelddadige stormen die het Zuidwesten troffen. De ene kwam op 7 augustus en was zwaar maar kortstondig, de tweede sloeg op 27 december toe met een ongekend geweld. Die duurde van zonsondergang tot de kleine uurtjes van de ochtend.',taste:'Mooie kleur, een fraai donkerrood, levendig en jong tegelijk. De neus geeft een sterke indruk van zachtheid en harmonie. Alle aromatische elementen staan volmaakt in verhouding: de zweem houtige vanille, de zoetheid van licht gekookte karamel, de lichte agressie van zoethout, rode en zwarte bessen, moerbei en kers versmelten tot een volmaakt evenwicht dat in de mond wordt teruggevonden, met een afdronk die lang en zoet is.'},
'haut-brion|2000':{note:'Een zacht begin van het jaar, een zeer natte, hete lente, gevolgd door een droge, verzengende zomer: dat waren de weerkenmerken van dit jaar, dat zowel door zijn jaartal als door de kwaliteit van de wijn legendarisch is geworden. Temperatuurrecords werden verbroken: 1,5 °C boven het gemiddelde over de twaalf maanden — een enorm verschil. September, heet en droog, volgde dat spoor en maakte het mogelijk in de best denkbare omstandigheden te oogsten.',taste:'Mooie kleur, zeer diep, waarin het robijnrood van Haut-Brion zich mengt met de purperviolette tint van de jeugd. De wijn in het glas laten walsen geeft een idee van zijn dichtheid. Die complexiteit komt terug in de aroma’s, die plotseling allemaal tegelijk losbarsten: een houtige zweem van fijn gepolijste eik, moerbeienjam, kersenpitten, een toets cassis en het bitterzoet van mango.'},
'haut-brion|2001':{note:'De weersomstandigheden waren tamelijk vergelijkbaar met die van 2000. Juli en augustus waren zeer heet (22 dagen waarop de maximumtemperatuur boven 30 °C uitkwam) en tussen 20 juli en 20 september werden slechts twee dagen met zware regen opgetekend. Bij het begin van de oogst was de rijpheid volmaakt en de sanitaire toestand ideaal.',taste:'Zeer mooie kleur, dicht en jong voor de jaargang. De aroma’s springen, voor een jonge wijn, uit het glas. Weer een wijn die aromatisch in balans is. Het hout domineert niet in deze jonge wijn. De aanzet is zacht en smeuïg. Het aromatische evenwicht sluit in de mond aan bij dat van de zeer gesmolten tannine. Geen enkele tannische stijfheid; een lichte zoethoutkant versmelt in de zachtheid van de afdronk.'},
'haut-brion|2002':{note:'Het jaar was zeer droog, maar de geringe neerslag was goed verdeeld en zorgde ervoor dat de wijnstokken de regelmatige watergift kregen die ze nodig hadden. Een iets koelere zomer vertraagde de rijping, maar vanaf 9 september werden de omstandigheden ideaal om te oogsten: betrekkelijk hete, zonnige dagen en een voor het seizoen ongewone noordoostenwind.',taste:'Een verrassend dichte kleur, die ondanks haar diepte zeer helder blijft. Aanvankelijk verbergt een zekere terughoudendheid de aroma’s van de wijn, maar zijn rijkdom laat zich zeer snel voelen. De aanzet verrast door het gevoel van een dicht, zeer complex fruitvolume. Stukje bij stukje vult de tannine de mond. Ze is zijdeachtig, zacht en soepel, en daar komen milde tonen van zeer subtiel hout bij.'},
'haut-brion|2003':{note:'2003 was zonder twijfel een zeer uitzonderlijk jaar wat het weer betreft. Het verbrak niet het record van de laagste neerslag, dat in 1961 werd gevestigd (258 mm) voor de periode april tot en met september, maar 2003 komt daar met 263 mm onmiddellijk achteraan. Op het punt van de temperatuur werden echter alle records verbroken. De opgetelde gemiddelde dagtemperaturen voor die periode kwamen uit rond 3.161.',taste:'De oogst had hoge suikergehaltes laten zien. De rijkdom aan tannine is enorm en bereikt recordhoogtes in de Merlots en vooral in de Cabernets. De weelderige tannine is ook bijzonder rijp. Ze is overvloedig, zijdeachtig en zacht, vult de mond en bekleedt het gehemelte met genot. Vreemd genoeg verdwijnt de frisheid van het fruit in zulke omstandigheden gewoonlijk. Niets is minder waar in 2003.'},
'haut-brion|2004':{note:'Het jaar 2004 begon met een uiterst regenachtige maand januari. Ondanks dat uitgesproken vochtige begin bleek 2004 uiteindelijk juist krap aan vocht. De bloei begin juni vond plaats onder volmaakte klimaatomstandigheden en verliep snel, met een aangenaam evenwicht. De regen van augustus was grotendeels in de laatste twee weken geconcentreerd.',taste:'De neus is betrekkelijk discreet maar van grote helderheid, met beurtelings nuances van rood fruit, mineralen, hout en rook. In de mond vinden we complexiteit. Ondanks een enorme concentratie valt de tannine het gehemelte niet aan. De wijn is precies, lang en kaarsrecht. Achter zijn gevel van strengheid ontdekken we een wijn van grote elegantie en stijl.'},
'haut-brion|2005':{note:'2005 zal in ons geheugen blijven als een historisch droog jaar. Dat kenmerk liet zich al in de winter zien, toen een aanzienlijk vochttekort werd opgetekend. Ondanks een natte maand april bleef regen tot aan de oogst schaars. Het hele jaar door bleven de temperaturen aan de hoge kant. 2005 had klimaatomstandigheden die sterk leken op die van de legendarische jaargang 1949.',taste:'De kleur is zo dicht dat de wijn haast zwart lijkt. De neus heeft een aromatische intensiteit die verbijsterend is. Hij kan zijn herkomst nooit verloochenen, want we vinden er alle complexiteit in die Haut-Brion zo bekend kenmerkt: zijn tonen van rook, van sigaar en van geroosterde koffiebonen. Ook de zweem vers fruit is aanwezig: aalbes en kers. Vanaf de eerste aanzet verbluft deze wijn door zijn dichtheid.'},
'haut-brion|2006':{note:'De jaargang 2006 is de vrucht van een zeer contrastrijk klimaat. In dat jaar veranderden de omstandigheden het hele jaar door op een zeer ongewone manier, van het ene uiterste naar het andere. Gelukkig waren de lente en de zomer over het algemeen heet en droog. Honderd seizoenarbeiders, die dag na dag drie volle maanden werkten, stelden de wijnmaker in staat geduldig het absolute hoogtepunt van elk ras af te wachten.',taste:'Elegantie zou het woord zijn dat deze wijn het best beschrijft. Zijn kleur is een zeer diep rood. De neus, eerst terughoudend, opent zich zacht en langzaam. Minerale tonen worden gevolgd door rode bessen, en dan een aardse zweem die beheerst wordt door het aroma van versgemalen koffiebonen. Voor je het weet bekoort de wijn je met al zijn ongelooflijke complexiteit. De mond is zijdeachtig.'},
'haut-brion|2007':{note:'Winter en lente werden beide gekenmerkt door zachte en vochtige omstandigheden. Nooit hebben de tractoren zo onverdroten gewerkt om de wijnstokken en hun vruchten te beschermen. Vanaf eind juni werd aan de oostzijde vroeg ontbladerd, en werden dieven en scheuten zorgvuldig gedund om de last voor de wijnstok te verlichten en de overblijvende trossen beter te verdelen voor een betere beluchting.',taste:'Gewoonlijk is Haut-Brion een wijn met een zekere terughoudendheid, die de proever verplicht hem tegemoet te komen. Château Haut-Brion 2007 wijst op een verandering. De kleur is een zeer diep roodviolet. In de neus domineert eerst het rode fruit boven de onmiskenbare signatuur van ons bijzondere terroir. Deze wijn komt met oneindige charme op je af. De mond is zacht en aangenaam, dankzij een tannine-extractie die op deze jaargang was afgestemd.'},
'haut-brion|2008':{note:'Een regenachtige en koele lente remde de groei van de wijnstok en betekende een late start van de bloei. Daarbij vertraagde een betrekkelijk koude en lichtjes vochtige augustus de rijping van de druiven. Doordat de oogstperiode ongeveer tien dagen later begon dan de datum die het jaar ervoor was gekozen, was 2008 dus een tamelijk late jaargang. In zo’n geval hangt het gedrag van de wijnstok af van de kwaliteit van de bodem, maar ook in hoge mate van de wijnboer.',taste:'Mooie dichte rode kleur. De neus is zeer rijp en toont tonen van rood fruit, beheerst door braam en cassis. In de mond is de aanzet dicht en strak. De ontwikkeling is zeer indrukwekkend door het pure volume en de indrukwekkend zachte tannine. De aanwezigheid van het fruit is zeer aanhoudend, met een lange en aromatische afdronk. Deze wijn heeft veel smaak en expressie.'},
'haut-brion|2009':{note:'Het groeiseizoen begon onder een regenachtige lentelucht. De bloei verliep gelijkmatig en homogeen dankzij warme temperaturen en het ontbreken van regen eind mei en begin juni. Juli, augustus en september waren eveneens zeer droog. 2009 was in feite een van de droogste jaargangen van de laatste jaren, waardoor de druiven volmaakt uitrijpten. De oogst begon op de laatste dag van augustus en duurde tot de eerste week van oktober.',taste:'De purperrode kleur is het eerste teken van de concentratie van deze wijn. In het glas gewalst toont hij een diep, warm, zeer rijp bouquet. Château Haut-Brion 2009 is van begin tot eind vol smaak. Hij is zo rijk en geconcentreerd dat we in de verleiding komen het woord ‘dik’ te gebruiken. Die dikte is echter in geen enkel opzicht synoniem met zwaarte, dankzij een frisheid die er tegenwicht aan geeft.'},
'haut-brion|2010':{note:'Een droog jaar met een dorre zomer. Het weer tijdens het groeiseizoen, van begin april tot eind september, was het droogste sinds 1949. Dat watertekort veroorzaakte uitdroging in de wijnstokken, concentreerde het druivensap en bracht de hoogste waarden voort die ooit zijn gemeten, vooral in suikergehalte. De zeer koele nachten bevorderden de opbouw van anthocyanen, waardoor de rode wijnen van 2010 de diepste kleur hebben die in lange tijd is gezien.',taste:'Deze wijn heeft een voortreffelijke robijnrode kleur met purperen reflexen. Het aanvankelijk gesloten bouquet opent zich mooi bij beluchting. De wonderlijk subtiele aroma’s volgen elkaar snel op, beginnend met houtige boventonen, dan rode bessen, uitkomend op het karakter van het terroir: cacaopoeder, roosterende koffie en Havana-sigaren. De aanvankelijke zachtheid in de mond ontwikkelt zich geleidelijk tot het tannische geraamte zich prijsgeeft.'},
'haut-brion|2011':{note:'Een van de kenmerken van 2011 was een uiterst droge lente. Op grond van de gemeten neerslag in april, mei en juni was dit de droogste lente sinds 1949. Gelukkig bracht de zomer wat regen, waardoor de wijnstok zijn groei kon voortzetten. Met een droge september konden we in optimale omstandigheden oogsten.',taste:'Mooie diepe rode kleur. Intense neus van zeer rijp zwart fruit met zwemen cacaoboon. Bij beluchting springen de complexe, rokerige zoethouttonen die zo typisch zijn voor Haut-Brion uit het glas. De eerste indruk in de mond is zeer elegant. De wijn bouwt dan snel kracht op, maar niet ten koste van de zachtheid, met rijke tannine die uitbloeit in een mooie lange afdronk vol smaak.'},
'haut-brion|2012':{note:'De jaargang 2012 was ongelijkmatig, van de uitloop, die door een koele, natte maand april werd verstoord, tot de véraison, die zich over een lange periode uitstrekte. Gelukkig waren juli en augustus 2012 ideaal: warm en droog. Dat mooie zomerweer stelde ons in staat alles te doen wat in de wijngaard mogelijk was om het slechte lenteweer goed te maken.',taste:'De Merlot speelt in deze jaargang een bijzondere rol, want hij vormt twee derde van de uiteindelijke assemblage. De neus is subtiel, elegant en zeer complex, met delicate zwemen rood fruit, braam en cassis, en ook gullere tonen van zoethout, roosterende koffie, eik en een haast bloemige kant die zich niet laat omschrijven. De strak geweven structuur is vanaf het begin duidelijk.'},
'haut-brion|2013':{note:'2013 was een waar hindernissenparcours voor de wijnboeren. Om te beginnen verstoorde een regenachtige lente de bloei, met coulure en millerandage tot gevolg. Schimmelziekten werden toch grotendeels in de hand gehouden. De zomer was warm en droog, al verminderde een zware onweersbui in juli met harde wind de potentiële oogst. De oogst viel later dan gewoonlijk, met afwisselend zon en regen.',taste:'Diepe, donkerrode kleur. De neus is zeer diep, met krachtige aroma’s van zwart fruit en specerijen. De wijn begint tamelijk krachtig in de mond, maar verzacht in het midden en ontwikkelt een heerlijk fluweelachtige textuur. Het fijn gepolijste tannische geraamte wordt versterkt door een aanzienlijke concentratie en een vol, weelderig lichaam. De afdronk is zeer lang.'},
'haut-brion|2014':{note:'2014 werd gekenmerkt door een buitengewone indian summer die de jaargang redde. Mooi lenteweer bevorderde een goede start van het groeiseizoen. Moeilijke zomeromstandigheden vertraagden de rijping echter ernstig. Gelukkig was de maand september volkomen prachtig, met droog, uiterst zonnig weer en maxima rond 30 °C.',taste:'Het werkelijk mooie bouquet heeft tonen van zwart fruit zoals braam en cassis, naast empyreumatische boventonen. De wijn toont in de mond zachte, goed gestructureerde tannine, die van begin tot eind kracht met elegantie verenigt.'},
'haut-brion|2015':{note:'Het jaar 2015 lijkt, in heel ons land, het warmste en zonnigste sinds het begin van de meteorologische statistieken. Een lange hittegolf en droge periode zorgden voor uitstekende bloeiomstandigheden, tot in augustus de wonderbaarlijke regen kwam. Die regen stelde de wijnstokken in staat de noodzakelijke waterreserves op peil te houden en de voeding te leveren die voor een volmaakte rijpheid nodig was. De oogst begon in september.',taste:'Zeer mooie, diepe granaatrode kleur. De neus is rijp en geconcentreerd. Na walsen in het glas wordt hij complexer, met zwemen zeer rijp — maar niet overrijp — rood en zwart fruit. Er zijn ook nuances van zoethout en een soupçon kruidnagel. De wijn begint met een zeer zacht mondgevoel en toont onmiddellijk een enorm volume en diepte in alle opzichten, met smaken die aan rijp fruit doen denken.'},
'haut-brion|2016':{note:'Ondanks een winter en een lente met ingewikkelde klimaatomstandigheden — overvloedige regen en temperaturen onder de seizoensgemiddelden — verliep de bloei met een haast wonderbaarlijke gelijkmatigheid. De grote zomerdroogte eindigde met een regenachtige periode half september, die zeer gunstig was voor het einde van de rijpingscyclus. In oktober kwam geen regen onze oogst verstoren.',taste:'Helder rood met granaatrode en purperen reflexen. De neus is zeer expressief en complex: een combinatie van rood en zwart fruit, viooltjes en meer, plus een opmerkelijke indruk van frisheid! De wijn begint vol en sappig in de mond en ontwikkelt zich dan met een ongelooflijke verfijning, met rijke tannine en veel volume, maar zonder enige agressie. De wijn is breed van basis en dik, maar niet zwaar.'},
'haut-brion|2017':{note:'De vegetatieve groei begon op 13 maart en werd daarna versneld door een warme, zonnige lente. Twee vorstperiodes eind april herinnerden de wijnboeren eraan dat de wijnbouw kwetsbaar is en dat de natuur zich niet laat bedwingen. Het watertekort, dat in juli en augustus 50% bereikte, was een onderscheidend kenmerk van de jaargang. Dankzij aanzienlijke neerslag in juni bleven de wijnstokken echter van de droogte gespaard.',taste:'Mooi diep rood met purperen reflexen. De eerste indruk in de neus is die van een zeer elegante wijn, gemaakt van volmaakt rijpe druiven. Walsen in het glas geeft complexe aroma’s prijs, met rijp fruit, specerijen en zoethout. Al emblematisch voor ‘Haut-Brion’. Hij begint breed, strak geweven en subtiel in de mond, zonder enige hardheid. Daarna ontwikkelt de wijn heerlijke smaken.'},
'haut-brion|2018':{note:'De lente van 2018 werd gekenmerkt door veelvuldig onweersweer. Het groeiseizoen begon zeer goed, al werd het later vertraagd door een gewelddadige hagelbui op 26 mei. De wijnstokken herstelden zich toch tamelijk snel. De maand juni was betrekkelijk warm en gunstig voor een gelijkmatige bloei. Daarop volgde een hete zomer met weinig neerslag. De véraison vond plaats onder ideale omstandigheden.',taste:'Donkere, intense rode kleur. De eerste indruk in de neus is diep, kruidig en ongelooflijk complex, onderstreept door aroma’s van rijp zwart fruit. Hij begint zacht en goed gestructureerd in de mond en wordt vol, met een indrukwekkend volume en zachte tannine. De afdronk is ongelooflijk lang, versterkt door rijke smaken die niet zwaar en niet hard zijn. Zonder enige twijfel een zeer mooie Haut-Brion!'},
'haut-brion|2019':{note:'De winter van 2018-2019 was zacht en droog. Koele temperaturen in de lente vertraagden de groei van de wijnstok. De bloei vond plaats onder ideale omstandigheden, zonder coulure en zonder millerandage. Storm Miguel trok op 7 juni over Nouvelle-Aquitaine, al bleven onze druiven gelukkig gespaard. Zware, regelmatige neerslag was gunstig voor de vegetatieve groei.',taste:'Voortreffelijke diepe karmijnrode kleur. In het begin is het bouquet subtiel en intens tegelijk, met tonen van rijp fruit. De aromatische complexiteit van deze wijn komt bij beluchting naar voren. Hij begint wonderlijk zacht en delicaat in de mond en wordt vol, maar nooit agressief. De tannine is strak geweven, subtiel en verleidelijk, zonder enige hardheid. De afdronk is lang en aromatisch.'},
'haut-brion|2020':{note:'De winter van 2019/2020 is zacht en nat. De groeicyclus van de wijnstok begint zeer vroeg (het is het vroegste jaar na 1989). In de lente bevordert aanhoudende neerslag het opkomen van valse meeldauw, dus zijn we dubbel oplettend. Ook de bloei is zeer vroeg en verloopt zoals gewoonlijk. Van half juni tot half augustus zet een uitzonderlijk hete, droge periode in, waarin we drie hittegolven optekenen.',taste:'De kleur van deze Château Haut-Brion is een donker, stralend rood. Nog voor het walsen geeft de neus al frisse en kruidige tonen prijs. Walsen bevestigt een goede rijpheid van de druiven, zonder overdaad. De eerste smaak is ongelooflijk strak geweven en precies. De wijn is meteen uitgesproken aanwezig. De ontwikkeling is nooit geforceerd, maar wat een presence in de mond!'},
'haut-brion|2021':{note:'De zachtheid van de winter van 2021 brengt de uitloop al op 1 maart op gang. In de lente wordt april gekenmerkt door een zware vorstperiode in de Bordeaux. De ligging van de wijngaard van Haut-Brion bewijst opnieuw zijn onschatbare waarde, want de vorst spaarde de grote meerderheid van de percelen. Zware regen in mei en juni heeft weinig gevolgen voor de wijnstokken.',taste:'De kleur is een mooi, donker purper. De eerste neus is zeer aromatisch, fijn, compact en fruitig. Bij het walsen overheerst de fruitigheid, puur, fris en delicaat. De eerste smaak is kort, rijk en heerlijk. De indrukken van kracht en delicatesse smelten samen en wekken de belangstelling. Daarna ontwikkelt de wijn zich, vol en aaneensluitend. De structuur is mollig, fris en fruitig. Hij geeft een gevoel van genot.'},
'haut-brion|2022':{note:'Het begin van de winter van 2021 is regenachtig en laat de waterreserves in de bodem zich herstellen. Vanaf februari stijgen de temperaturen boven de seizoensgemiddelden en brengen een vroege start van de groeicyclus van de wijnstok. Het eerste deel van april wordt gekenmerkt door een vorstperiode, breder verspreid maar minder zwaar dan die van het jaar ervoor. Voor de wijnstokken van Haut-Brion is het effect minimaal.',taste:'De kleur is diep en magnifiek. De neus is betoverend. Walsen bevestigt die indruk van volmaakte fruitigheid. De hete zomer laat zich niet zien: de wijnstok antwoordde op de uitersten van het weer van 2022 en de druiven zijn rijp, precies rijp. De wijn in het glas walsen verleidt ons er vanzelf toe verder te gaan. De eerste smaak is breed, strak, meeslepend en precies.'},
'haut-brion|2023':{note:'De winter was regenachtig en betrekkelijk koud. Zodra de uitloop half maart op gang kwam, was de groei van de wijnstok uiterst krachtig, aangewakkerd door regelmatige neerslag en warme dagen. Die snelle groei vroeg van de ploegen dat ze in de wijngaard in actie kwamen, waar de waakzaamheid over de gezondheid van de wijnstok onberispelijk moest zijn.',taste:'Een mooie donkere, diepe rode kleur met purperen glinsteringen. In dit stadium is hij tamelijk discreet in de neus. Walsen geeft een complexe veelheid aan aroma’s prijs, met tonen van volmaakt rijp rood en zwart fruit. Er zijn al zwemen zoethout en rokerige tonen, voortekenen van voortreffelijke flessen van deze wijn. De eerste smaak is opmerkelijk om zijn zachtheid en zijn onmiddellijke presence.'},
'haut-brion|2024':{note:'Al viel 2024 op als een tamelijk koel jaar, het werd toch voorafgegaan door een zachte en natte winter, waardoor de uitloop vroeg begon, al vanaf half maart. Die voorsprong werd echter afgeremd door aanhoudende neerslag, die de groei van de vegetatie vertraagde. In de wijngaard stonden de ploegen volledig klaar om bij het begin van de lente in actie te komen en de gezondheidstoestand van de wijngaard nauwlettend te volgen.',taste:'Een schitterende donkere, granaatrode kleur. De eerste neus is krachtig, zeer fruitig en rijp. Bij het walsen worden die indrukken sterker; het is betoverend! De aanzet is breed, vlezig en gracieus. De wijn vult de mond met een zachte, gulle presence. De tannine is merkbaar, sappig en soepel. De drie druivenrassen zijn samengebracht tot een volkomen ideaal evenwicht tussen de aroma’s, de smaken en de elegantie van de tannine.'},
'haut-brion|2025':{note:'Op een droge, kille winter volgde een uitloop die lichtjes vroeg kwam. Helder en zonnig trok de lente de wijnstok mee in haar beweging, legde de ploeg een zwaar tempo op en maakte het nodig de wijngaard zeer nauwlettend in het oog te houden. Bloei en vruchtzetting verliepen onder uitstekende omstandigheden en beloofden een opmerkelijk kwaliteitspotentieel, al beperkt in hoeveelheid door een zwakke bloemaanleg.',taste:'De tint is diep rood, levendig en sterk van kleur, met wisselende purperen glinsteringen. De eerste neus is subtiel, zeer terughoudend en elegant, trouw aan de identiteit van Haut-Brion. Dan komen bloemige geuren, gevolgd door zwemen zwart fruit, kers en zelfs een toets eucalyptus. De wijn voelt precies; hij ontvouwt zijn structuur, waarvan de compactheid haast getextureerd en uiterst gracieus is.'},
'kirwan|2023':{note:'Hij krijgt bij zijn vinificatie dezelfde technische aandacht in de wijngaard en in de gistingsruimte: perceelselectie, dubbele sortering zodra de oogst binnenkomt, vullen van de betonnen kuipen op zwaartekracht en zacht geleide vergistingen.'},
'la-conseillante|2001':{taste:'De aanzet in de mond is zacht en fruitig, maar dan nemen elegante tannines het over en maken hem groter. De afdronk is mild en eindigt met de eerste tonen van evolutie, zoals leer.'},
'la-conseillante|2002':{note:'Een zeer heldere winter met een zeer droge en koude helft, gevolgd door een zeer zachte en nattere periode.',taste:'De afdronk is zeer aangenaam en geeft een zijdeachtige textuur en een elegant bouquet prijs, dankzij de vaste maar goed omhulde tannine.'},
'la-conseillante|2009':{taste:'Het kenmerk van deze jaargang ligt in het zijdeachtige en de zeer vroege integratie van de tannine in hoe ze in de mond wordt waargenomen.'},
'la-conseillante|2011':{taste:'De Merlots tonen een mooie rijpheid, met veel fruit en goed geïntegreerde tannine.'},
'la-conseillante|2012':{note:'2012 is een jaar dat een vroege groei en rijping duidelijk in de hand werkte. De wijngaarden die het eerst werden geoogst, brachten betere wijnen voort dan die later werden geplukt.'},
'la-conseillante|2021':{note:'Deze zomer van 2021 zal dus gekenmerkt blijven door een op zijn minst ongewone rijpingscyclus van de druiven. Zoals vaak in Bordeaux bleken het einde van de zomer en het begin van de herfst een zegen: september was minder vochtig en warmer dan gewoonlijk, terwijl oktober wat koeler maar duidelijk droger uitviel dan normaal.'},
'la-conseillante|2023':{note:'De bloei was vroeg, gelijkmatig en explosief en kondigde een gulle oogst aan. In september versnelden warme temperaturen de rijping, wat op een vroege oogst wees.'},
'la-lagune|2012':{note:'De winter van 2012 verliep zeer koud, met een groot neerslagtekort, ondanks enkele sneeuwperiodes. Het seizoen was paradoxaal: ondanks een bijzonder natte en koele lente was de hoge verdampingsvraag in mei, met een stevige wind tijdens de enkele droge periodes, genoeg om de waterbalans snel negatief te maken.'},
'la-lagune|2014':{note:'Na een goed doorregende herfst in 2013 kwam de bijzonder zachte winter van 2014 in zijn eerste drie maanden op 440 mm. De lente begon met een zonnige maand april en werd daarna onderbroken door onweersbuien.'},
'la-lagune|2015':{note:'Na een zachte herfst in 2014, met een bijzonder regenachtige maand november, verliep de winter van 2015 koud en droog. Na een tamelijk late uitloop liet het goede lenteweer de plant haar achterstand snel inhalen.'},
'la-lagune|2016':{note:'Na een zachte en weinig regenachtige herfst in 2015 was de winter van 2016 uitzonderlijk zacht en nat. De volle bloei werd half juni bereikt, in een periode die wat droger en vooral warmer was.'},
'la-lagune|2017':{note:'Na een zachte en weinig regenachtige herfst in 2016 verliep de winter van 2017 uitzonderlijk droog en koud. Het einde van de winter en het begin van de lente, zachter en vochtiger, bevorderden een vroege uitloop.'},
'la-lagune|2019':{note:'De winter van 2019 werd gekenmerkt door temperaturen binnen de seizoensnormalen en zeer geringe neerslag. September kwam en de rijping zette zich voort, met een gezonde wijngaard en druiven van goede kwaliteit.'},
'la-lagune|2020':{note:'De winter van 2020 werd gekenmerkt door temperaturen boven normaal en zeer geringe neerslag. We zagen de eerste bloemen op 15 mei en het begin van de véraison op 7 juli.'},
'la-lagune|2021':{note:'De winter van 2020-2021 begon met een tamelijk droge en zachte maand november. De wijnstok ging snel weer groeien en bij die gelegenheid verliep ook de bloei.'},
'la-lagune|2022':{note:'Na een regenrijk einde van 2021 was het eerste kwartaal van 2022 tamelijk droog, wat de toon zette voor het verdere verloop van de jaargang. De winter van 2022 werd gekenmerkt door zijn zachtheid, met in februari en maart temperaturen rond 20 °C.'},
'la-mission-haut-brion|2024':{note:'2024 was zonder twijfel koeler dan de voorgaande jaren, maar de natte en uitgesproken zachte winter was er verantwoordelijk voor dat de uitloop bijna twee weken vroeg kwam, al vanaf half maart. In de maanden daarna vestigde zich nat weer voor langere duur, met zware neerslag, en dat zorgde voor een vertraging in de groei van de wijnstok.',taste:'Een mooie granaatrode tint met purperen glinsteringen. Hij is krachtig, geconcentreerd en complex in de neus. Al zeer kenmerkend voor deze wijn! Walsen geeft een weelde aan rood en zwart fruit prijs, met toetsen zoethout. Het is magnifiek! De aanzet is breed en vlezig. Daarna ontwikkelt de wijn zich zeer charmant, met zachtheid, volheid en een ongelooflijke smaak.'},
'la-mission-haut-brion|2025':{note:'Een droge, kille winter bereidde de weg voor een lichtjes vroege uitloop en een in licht gebade lente die de beweging van de wijnstok begeleidde. De ploegen stemden het tempo van hun werk af op elk teken van de levende organismen en hielden de wijngaard onophoudelijk in het oog. Bloei en vruchtzetting waren volkomen gelijkmatig en verliepen onder ideale omstandigheden.',taste:'Een schitterende, lichtende rode tint, verfraaid door dieprode glinsteringen. Vanaf de eerste neus is de wijn expressief, complex, verrukkelijk en zo typisch voor deze wijngaard. Dat komt bij het walsen nog verder naar voren, met zwemen zwart fruit, cassis en tonen van mokka. Bij het proeven is de eerste indruk krachtig, met een heldere structuur.'},
'lafon-rochet|2007':{taste:'Een evenwichtige, frisse en precieze neus. Tonen van specerijen en witte peper in de mond, met uitstekende lengte en fluweelachtige tannine die het gehemelte bekleedt. Alles bij elkaar een verrassende jaargang, die een gulle wijn geeft die nu klaar is om gedronken en gedeeld te worden. Wij raden aan de wijn vóór het proeven te openen en te karafferen.'},
'lafon-rochet|2008':{taste:'Onze jaargang 2008 heeft een complexe en sterk geparfumeerde neus van rood fruit, rijpe wijngaardperziken en kruidige tonen (zwarte peper en nootmuskaat). De structuur is van begin tot eind evenwichtig en elegant. De tannine is fijn, met een afdronk die de aanvankelijke geurige fruitneus weerspiegelt. Wij raden aan de wijn vóór het proeven te openen en te karafferen.'},
'lafon-rochet|2009':{taste:'Een complexe neus die tonen van rood fruit en hout prijsgeeft, al is hij tamelijk gesloten. Er zijn ook aroma’s van cassis en bosbes. In de mond is de combinatie van alle elementen — tannine, hout, fruit en zoetheid — geslaagd. Deze heerlijk smaakvolle wijn toont een mooie textuur, met goed gestructureerde, aangename tannine. Wij raden aan de wijn vóór het proeven te openen en te karafferen.'},
'lafon-rochet|2011':{taste:'Een evenwichtige, fruitige neus die nog enigszins terughoudend is. In de mond delicaat en dicht, met mooie zuren en goede lengte. Onze 2011 is licht en zal de komende vijf jaar goed drinken, maar kan zich ook in de jaren daarna nog openen. Wij raden aan de wijn vóór het proeven te openen en te karafferen.'},
'lafon-rochet|2013':{taste:'De jaargang 2013 van Château Lafon-Rochet is een fruitige en vrouwelijke jaargang. De tannine is elegant en fijn, en over een paar jaar zal hij zich prijsgeven, met zijn prachtige aromatische complexiteit.'},
'lafon-rochet|2014':{taste:'Een onbetwistbaar klassieke jaargang. Een natuurlijk krachtige, gestructureerde wijn met een vlezige aanzet, mooi rond met een zachte en evenwichtige zoetheid. Het midden van de mond is strakker en klassieker. De afdronk is de volmaakte vertegenwoordiging van het jaar: lang, soepel en vol geduld.'},
'lafon-rochet|2016':{taste:'De jaargang 2016 van Château Lafon-Rochet heeft een opmerkelijke kracht en lengte, die het proeven veel elegantie geven.'},
'lafon-rochet|2017':{taste:'De neus is fijn en getoast, met zoethout, en laat na walsen kersentonen opkomen, licht peperig. De aanzet is vlezig en zacht met zijdeachtige tannine. Goed in balans in de mond, met pittige tonen. De afdronk brengt zoetheid en frisheid, en vindt het zoethout terug.'},
'lafon-rochet|2018':{taste:'Een expressieve neus, op frisheid, met knapperig rijp fruit en rode bessen (cassis, aardbei, framboos). Een heldere aanzet, fris, met zich spreidende tannine en een fijne structuur. Soepele en complexe afdronk met een heerlijk fruitige aromatische nasmaak, kaneel.'},
'lafon-rochet|2020':{taste:'Aanvankelijk wat gesloten opent de neus zich fijn en elegant op tonen van rode bessen. De fruitige aanzet, met zachte tannine, loopt uit op een lichte afdronk. Nog een paar jaar kelder zal zijn toch al complexe aroma’s goeddoen.'},
'lafon-rochet|2021':{taste:'De discrete neus is fris, mooi in balans tussen fruitigheid en geroosterde tonen. Het midden bevestigt zijn frisheid, naast een sterke aanwezigheid van fruit met geïntegreerde tannine. De afdronk is zeer belovend wat zijn bewaarpotentieel betreft.'},
'lafon-rochet|2023':{note:'De bloei vond plaats in de laatste twee weken van mei, bij mild weer. Met lenteomstandigheden die warmer maar even nat waren als wat we in het verleden hebben meegemaakt, is dit bij uitstek een jaargang die door de klimaatverandering is geraakt.'},
'lagrange|2023':{note:'Al was er minder zon dan in een jaargang als 2022, ze lag nog altijd ruim boven het gemiddelde van de afgelopen twintig jaar.'},
'lagrange|2024':{note:'Deze gegevens komen van het weerstation van Château Lagrange zelf, dat er sinds de winter van 1996 staat. Met een jaarlijkse neerslag van 1.053 mm komt 2024 in de top drie van de natste jaargangen sinds 1997.'},
'lagrange|2025':{note:'Deze gegevens komen van het weerstation van Château Lagrange zelf, dat er sinds de winter van 1996 staat. Met een jaarlijkse neerslag van 830 mm tekent 2025 een totaal op dat duidelijk onder het gemiddelde sinds 1997 ligt.'},
'lynch-moussas|2020':{note:'Door een tamelijk droge en zachte winter was de uitloop twee weken vroeger dan in 2019: de eerste knoppen kwamen op 26 maart bij de Merlots! De véraison begon op 6 juli en duurde bij sommige percelen drie tot vier weken.'},
'marquis-de-terme|2016':{note:'Dit jaar 2016 werd gekenmerkt door een uitzonderlijk zachte winter. De zomertemperaturen waren normaal tot half augustus, waarna de indian summer zich rustig vestigde tot half november.'},
'marquis-de-terme|2017':{note:'Na een tamelijk strenge winter bleek het oceanische klimaat dat voor de Bordeaux kenmerkend is een troost tijdens de zomer. De afwisseling van zon, wolken, regen en wind leidde tot een zachte rijping van de druiven.',taste:'Trouw aan de neus levert de mond de fijnste geroosterde tonen van vanille en mokkakoffie, met kirsch in de afdronk. Stijlvol tot in de afdronk, met fijne zuren die hem mooi laten nazinderen.'},
'marquis-de-terme|2018':{note:'Een contrastrijke winter maakte plaats voor een lente die even zacht als nat was. De uitzonderlijke zon en hitte van juli en augustus droogden de bodems uit en wekten de waterstress die de kwaliteit ten goede komt.',taste:'Een complex, dicht en expressief bouquet, op tonen van cassis en braam met een peperige rand. De tannine is verleidelijk, dicht, krachtig en omhuld, alles tegelijk.'},
'marquis-de-terme|2021':{note:'Onze diepe grindbodems kwamen bijzonder goed tot hun recht onder complexe omstandigheden: een zachte winter, een koele en natte lente tot in juni, daarna een hete, droge zomer die onze Cabernet Sauvignon bijzonder goed lag.',taste:'De maanden september en oktober speelden hun rol en maakten de rijpheid volmaakt af. Overvloedige tannine die zich in de afdronk sluit en op een lang leven wijst.'},
'marquis-de-terme|2022':{note:'Onze diepe grindbodems zijn bijzonder goed tot uitdrukking gekomen tegenover ingewikkelde klimaatomstandigheden: een zachte winter, een koele en regenachtige lente tot in juni, gevolgd door een hete en droge zomer die onze Cabernet Sauvignon bijzonder goeddeed.'},
'marquis-de-terme|2023':{note:'De zomer was heet en zonnig.',taste:'Frisse aalbes, donkere olijven, bosvruchten en geroosterde specerijen in de neus. Middelvol tot vol, met fijnkorrelige tannine en een stoffige, gesmolten afdronk.'},
'montrose|2014':{note:'Winter: zacht, weinig regen. Lente: droog, met een hagelbui eind juni. Zomer: zeer heet, temperaturen boven normaal. Herfst: warm en droog, met druiven die gelijkmatig doorrijpten. Dichte, diepe kleur.',taste:'Een krachtige aanzet met uiterst fijne, fluweelachtige tannine.'},
'montrose|2015':{note:'Winter: koel en zonnig. Lente: droog, met een snelle en gelijkmatige bloei begin juni. Zomer: droog, met een vroege en gelijkmatige véraison. Herfst: buien in september, maar een volmaakte drainage dankzij het terroir. Een diepe robe, en een expressieve, elegante neus met tonen van witte bloemen.',taste:'De neus geeft complexe aroma’s van rijp zwart fruit, rook en toast prijs. Waar fluweel, met zijdeachtige tannine en een zeer mooi evenwicht.'},
'montrose|2016':{note:'Winter: zacht met gematigde regen. Lente: regenachtig met wat hagel eind juni. Zomer: zeer heet met temperaturen boven normaal. Herfst: warm en droog. Een zeer donkere robe, intens en diep.',taste:'Een complexe neus, levendig en precies, van goed uitgerijpt fruit met houtige, geroosterde tonen en een kruidige toets.'},
'montrose|2017':{window:'Een jaargang die de signatuur van zijn terroir draagt, met een zeer mooi bewaarpotentieel.',taste:'Een ruime, elegante mond, aanhoudend sappig, met soepele, gesmolten tannine.'},
'montrose|2018':{taste:'Een delicate, complexe neus, op aroma’s van zwart fruit en witte bloemen met subtiele rokerige tonen. Een krachtige, zijdeachtige afdronk van ongelooflijke lengte en finesse.'},
'montrose|2019':{note:'Winter: zacht, weinig regen. Lente: droog met een hagelbui eind juni. Zomer: zeer heet met temperaturen boven normaal. Herfst: warm en droog. Een intense robe van zeer diep rood.',taste:'Een dichte, volmaakt gestructureerde mond, met aroma’s van goed uitgerijpt fruit en zijdeachtige tannine.'},
'montrose|2020':{note:'Winter: zacht met weinig regen. Lente: zeer warm, zware regen in mei en juni, vroege bloei op 22 mei. Zomer: droog met hittegolven eind juli en half augustus, getemperd door regen in augustus. Herfst: een vroege oogst in goede omstandigheden, ondanks wat regen. Een intens purperen robe.',taste:'De mond is ruim, opwekkend en geconcentreerd en biedt een smeuïge substantie. De afdronk, lang en aanhoudend, komt met zijdeachtige tannine.'},
'montrose|2021':{taste:'De mond is krachtig en gestructureerd, met aroma’s van frisse eik en onderhout.'},
'montrose|2022':{taste:'Bij beluchting mentholachtige en zalvende tonen, daarna aroma’s van lichte tabak, specerijen en braam. Een frisse, zilte mond met krachtige maar beheerste tannine.'},
'montrose|2025':{taste:'De neus, fris, precies en zeer complex, opent met delicate tonen van witte bloemen, lelietje-van-dalen en versgesneden stelen, opgetild door een levendige toets citrus. De mond zet zich met intense levendigheid door. Breed en omhullend wordt de textuur gedragen door een lange en krachtige structuur, die zich met aanhoudende energie ontvouwt. Een jaargang van triomfantelijke intensiteit, gedreven door een meesterlijk evenwicht.'},
'mouton|1982':{taste:'De kleur is dicht en diep met een lichte amberen tint, terwijl de neus aroma’s van ontbijtkoek, munt, zeer rijp fruit, cassis en bosbes prijsgeeft, met tonen van kaneel, toast en mokka. Uit een vaste en zijdeachtige aanzet met een elegant tannisch geraamte van fluweelachtige, patricische tannine ontwikkelt de wijn een vol, rond lichaam met zwemen zoethout en karamel. Fris, stijlvol, verleidelijk en charmant.'},
'mouton|1983':{taste:'Een aantrekkelijk intens purper met een lichte baksteenachtige tint; de wijn toont een verfijnde, frisse en rijk aromatische neus die aroma’s van specerijen, cacao, karamel en koffiedik verbindt met een toets munt. De aanzet is soepel en rijk, met patricische, zijdeachtige tannine, omhuld door een schat aan uiteenlopende smaken: zwart fruit, wierook, cederhout en lichte tabak, samen met enkele peperige tonen.'},
'mouton|1984':{taste:'Een glinsterend helder rood met een lichte amberen tint. De zeer verfijnde en elegante neus biedt aroma’s van koffie, zoethout en rood fruit, geschraagd door aangenaam hout. Uit een ronde en rijke aanzet maakt de indruk van substantie en opulentie plaats voor zijdeachtige en volmaakt evenwichtige tannine, harmonieus verbonden met het hout.'},
'mouton|1985':{taste:'De wijn heeft een intense rode kleur die net de eerste tekenen van ouderdom toont, en een neus die aroma’s van rijp fruit prijsgeeft — braam, bosbes en cassis — samen met toetsen munt, wierook, vanille en cacao. De aanzet is rond en zacht, op volledig geïntegreerde tannine, terwijl het volle en gulle lichaam smaken van karamel en rijp fruit toont, uitlopend op een lange afdronk met tonen van specerijen.'},
'mouton|1986':{taste:'Een donkere, intense kleur met een robijnen tint; deze mooie jaargang geeft een neus van noten en pruimen prijs, complexer gemaakt door tonen van toffee, rancio, peperige specerijen en cederhout. De aanzet is dicht, de tannine naar voren en strak geweven, de wijn krachtig, rijk en zacht, met een weelde aan smaken van fruitjam, wilde bessen en cassislikeur, uitlopend op een afdronk met tonen van toast.'},
'mouton|1987':{taste:'De wijn is donkerrood, naar oranje verschuivend aan de rand, terwijl de neus tonen van wax en fruit prijsgeeft, vooral framboos en kers, met aroma’s van humus en leer. De aanzet is elegant, nog met een toets frisheid. Er is vanille in de mond, de tannine is goed geïntegreerd, de textuur is zijdeachtig. Dit is een prachtig harmonische wijn, met een afdronk op smaken van rijp fruit en specerijen.'},
'mouton|1988':{taste:'De wijn is donkerrood met een koperen tint. De neus opent op aroma’s van toast, samen met bloemige tonen (lelie), karamel, lichte tabak, zoethout en vanille, en geeft bij beluchting een minerale kant prijs. De aanzet is vol en gul, op kauwbare tannine. Verrassend om zijn frisheid en kracht eindigt de wijn aangenaam op tonen van kirsch, munt en koffie.'},
'mouton|1989':{taste:'De wijn heeft een diepe kleur met een aantrekkelijke robijnen en granaatrode tint. De aangenaam rokerige en geroosterde neus geeft ook tonen van zoethout, specerijen en cederhout prijs. De aanzet is rond, met veel fruitige frisheid over aanhoudende, zijdeachtige tannine en subtiele toetsen karamel, wilde bessen, vanille, koffie en witte peper. De lange afdronk is gul, harmonisch en mooi in balans. Werkelijk een zeer mooie jaargang.'},
'mouton|1990':{taste:'De wijn heeft een heldere, glinsterende kleur met een lichte baksteenachtige tint, terwijl de open en expressieve neus goed ontwikkelde aroma’s van lichte tabak en wild biedt, samen met enkele zeer aangename minerale tonen. De aanzet is zacht en geleidelijk, terwijl het verfijnde en zijdeachtige tannische geraamte erop wijst dat deze Mouton Rothschild zijn volle rijpheid heeft bereikt.'},
'mouton|1991':{taste:'De wijn heeft een baksteenachtige kleur met een aantrekkelijke, lichtjes oranje tint. De neus toont tamelijk verfijnde aroma’s, met subtiele bloemige toetsen jasmijn en meer naar voren komende geroosterde tonen. Toetsen cassis en specerijen versterken de eerste neus bij beluchting. De mond is fris en vol, op zuurzoete bosvruchten, met verfijning en elegantie op ronde, goed geïntegreerde tannine, zo zacht als maar kan.'},
'mouton|1992':{taste:'De wijn heeft een purperen kleur, naar oranje verschuivend aan de rand, en een elegante neus op tonen van karamel en tabak. Het fruit, eerst lichtjes terughoudend, opent zich bij beluchting en biedt aantrekkelijke humusaroma’s. Het tannische geraamte is strak geweven en vast in de mond, met een zeer elegante textuur. De algehele indruk is harmonisch en aangenaam, met een prettig lange en gestructureerde afdronk.'},
'mouton|1993':{taste:'De wijn heeft een heerlijke, diepe kleur met een lichtjes oranje tint en een open, verfijnde neus die aroma’s van cassis, leer en koude rook toont, samen met delicate karameltonen. Hij is vanaf de aanzet rond, naar voren en rijk van smaak, met warme humustonen die zich met zwart fruit vermengen, en toont een voortreffelijk evenwicht in het midden van de mond, waar de tannine fluweliger wordt. De afdronk is lang en compact.'},
'mouton|1994':{taste:'De wijn is een diep en donker granaatrood dat aan de rand lichtjes verschuift, terwijl de complexe neus tonen van leer en wax toont met een lichtjes dierlijke inslag, alles elegant afgezet tegen een bloemige onderlaag en aantrekkelijk hout. De soepele en precieze mond toont een goed evenwicht, met goed geïntegreerde tannine en een opulentie die de structuur omhult. De smaken blijven hangen in een lange, fruitige afdronk.'},
'mouton|1995':{taste:'Een donkere en diepe kleur; de wijn heeft een ongecompliceerde maar ook precieze en nobele neus waarop aroma’s van fruitjam en gekonfijt fruit overheersen, met een opening naar vruchten op alcohol. De mond is fris en complex tegelijk, met gekonfijt fruit naast smaken van zoethout. Dichte en kauwbare tannine blijft de wijn een mooie structuur geven, terwijl nazinderende fruitsmaken doorlopen in een lange en warme afdronk.'},
'mouton|1996':{taste:'Een aantrekkelijk rood dat aan de rand lichtjes naar oranje verschuift; de wijn heeft een open en intense neus op aroma’s van zwart fruit als kers en braam, samen met cederhout, frisse munt, enkele meer bloemige tonen en volmaakt geïntegreerd hout. Vanaf het begin biedt de volle mond opulentie en een aantrekkelijke dichtheid, met een opmerkelijke smaakdiepte.'},
'mouton|1997':{taste:'Een ontwikkelde, baksteenachtige kleur met een lichtjes oranje tint. De wijn heeft een intense neus op aroma’s van leer, hyacint en tabak. In de mond is hij rond en fruitig, met aanhoudende en fijne tannine. Het fruit, met kruidige en rokerige tonen, geeft een langdurige afdronk. Een bijzonder geslaagde jaargang.'},
'mouton|1998':{taste:'Diep van kleur is de wijn een aantrekkelijk purperrood. De betrekkelijk discrete eerste neus toont aroma’s van zwart fruit, cassis en leer met een minerale inslag, terwijl bij beluchting intensere, houtige tonen opkomen, samen met een toets mokka. De heldere en goed gestructureerde aanzet toont een heerlijke, zuurzoete frisheid die een textuur van hoge kwaliteit aankondigt.'},
'mouton|1999':{taste:'De wijn heeft een ontwikkelde kleur met een lichtjes oranje, baksteenachtige tint aan de rand en een diepe en complexe neus die een weelde aan aroma’s biedt van gestoofd fruit, zwart fruit, tabak, specerijen (kruidnagel) en peper. De aanzet is fris, op rijp fruit met een aantrekkelijk minerale toets, terwijl zuurzoete bosvruchten in de mond een romig zacht en precies tannisch geraamte aanvullen.'},
'mouton|2000':{taste:'De wijn heeft een aantrekkelijk diepe kleur met een granaatrode tint en een open, complexe neus die beheerst wordt door tonen van humus en varen, samen met fruitjam en pruimen. Vol in de aanzet toont hij opulentie en een aantrekkelijke substantie over strak geweven, strelende tannine, en ontwikkelt intense tonen van geroosterde koffie, afgezet tegen een heerlijke herinnering aan de humusaroma’s in de neus.'},
'mouton|2001':{taste:'De wijn heeft een ontwikkelde, granaatrode kleur met schitterende reflexen. De neus toont complex fruit, rijk aan aroma’s van rijpe bosvruchten als bosbes en cassis, met enkele aangename tonen van rook en leer en een lichtjes dierlijke inslag. Uit een goed gestructureerde aanzet, gedragen door mooi ronde tannine, komen bevredigend dichte smaken in de mond op, vol fruit.'},
'mouton|2002':{taste:'Een heerlijk, helder en glinsterend robijnrood van opmerkelijke intensiteit; de wijn heeft een neus die opent op gulle dierlijke tonen en zich daarna ontwikkelt met fruitaroma’s van braam en cassis, waarbij elegant hout zich verbindt met een toets mineraliteit. De aanzet is dicht en rijk, op nog vaste, verfijnde en zeer mooi ronde tannine.'},
'mouton|2003':{taste:'De wijn heeft een prachtig intense, granaatrode tint en een zeer verfijnde neus, tamelijk typisch voor Cabernet, op aroma’s van cassis en cederhout, samen met karamel en gestoofd fruit. De aanzet is weelderig, de mond rijk, op stijlvolle, mooi ronde tannine; fruitsmaken schurken aan tegen specerijen, Havana-sigaar en eucalyptus. De afdronk is zeer expressief, lang en krachtig, harmonisch en zijdeachtig.'},
'mouton|2004':{taste:'De wijn heeft een sterke, donkere en diepe kleur, terwijl de neus een subtiele complexiteit toont op fruitige tonen van zwarte kers, gekonfijte kweepeer en zoethout met toetsen koude rook, en zeer goed geïntegreerd hout prijsgeeft. De aanzet is rijk en vol, met precieze, verfijnde tannine die elegant mokkasmaken en geroosterde tonen omhult, uitlopend op een strak geweven en smaakvolle afdronk met een aantrekkelijke, zeer frisse lengte.'},
'mouton|2005':{taste:'De wijn heeft een aantrekkelijke kleur, donker, diep en nog zeer jong, en een elegante, complexe neus die verfijnde tonen van hout, toast en vanille verbindt met intens fruit van wilde bessen. Toetsen munt en specerijen maken het geheel af en brengen frisheid en oorspronkelijkheid. De mond is krachtig en substantieel tegelijk en geeft aantrekkelijk strak geweven, sappige en weelderige tannine prijs.'},
'mouton|2006':{taste:'De wijn is een aantrekkelijk, intens en donker kersenrood. Met de Cabernet Sauvignon in de hoofdrol brengt de assemblage van Château Mouton Rothschild 2006 een complexe en intense weelde aan aroma’s tot uitdrukking, die fruit (bosbes) en melkachtige tonen verbindt met de geroosterde aroma’s (lichte tabak, wierook, geroosterde hazelnoot) van verstandig gebruikt hout. De precieze en harmonische aanzet wordt verlengd door frisse en knappende, rijk smakende tannine.'},
'mouton|2007':{taste:'De wijn heeft een intense granaatrode tint met glinsterende reflexen. Alle diepte en verfijning van de Cabernet Sauvignon komt in de neus tot uitdrukking in aroma’s van vanille, bittere amandel en nootmuskaat, met bij beluchting subtiele minerale tonen. Zeer soepel in de mond toont deze Mouton Rothschild een volmaakte harmonie op een lineaire structuur die tannisch gewicht verbindt met een aangename muntfrisheid. De afdronk is complex.'},
'mouton|2008':{taste:'Met opnieuw een zeer hoog aandeel Cabernet Sauvignon in de assemblage toont deze Mouton Rothschild het hele proeven door een zeer rijk palet aan aroma’s en smaken. De eerste neus is intens en open: rood fruit, braam en cassis verbinden zich harmonieus met bloemige tonen als viooltje. Bij beluchting vermengen geroosterde tonen zich gracieus met delicate toetsen cederhout.'},
'mouton|2009':{taste:'De wijn heeft een zeer diepe, haast zwarte kleur met glinsterende reflexen. De stijlvolle en complexe neus biedt een brede weelde aan aroma’s, waarbij bosbes, cassis en lichte tabak zich vermengen met subtiel cederhout en specerijen. De mond toont onmiddellijk alle dichtheid en verfijning van de wijn: zeer naar voren komende smaken van rijp fruit zijn volmaakt geïntegreerd met patricische, mooi ronde tannine, met een opmerkelijke structuur en balans.'},
'mouton|2010':{taste:'De wijn is een donker en intens rood. Met de Cabernet Sauvignon in de hoofdrol toont Mouton Rothschild 2010 een complex palet aan aroma’s. Vanuit lichtjes geroosterde vanilletonen opent de neus zich bij beluchting en ontwikkelt fruitaroma’s, vooral cassis en zwarte kers. De aanzet toont een grote complexiteit, terwijl krachtige en goed geïntegreerde tannine een uitzonderlijke diepte en rondheid prijsgeeft. Een frisse en minerale afdronk maakt het af.'},
'mouton|2011':{taste:'De kleur is intens, een donkerrood met schitterende reflexen. De uiterst elegante neus toont aroma’s van rood fruit met toetsen specerijen. In de mond maakt een zachte, romige aanzet plaats voor krachtige, fluweelachtige tannine. De rondheid is opmerkelijk en geeft de wijn een zeer aantrekkelijke lengte. De afdronk geeft aroma’s van vanille en chocolade prijs, met aangename bloemige tonen. Een zeer mooie, klassieke Mouton en een groot succes in een lastige jaargang.'},
'mouton|2013':{taste:'De kleur is een intens, diep rood met een karmozijnen tint. De complexe neus toont eerst aroma’s van zwarte kers, framboos en braam en opent zich bij beluchting met kruidige en delicaat geroosterde tonen. Uit een heldere, frisse en rijke aanzet breidt de mond zich uit op zwemen vanille en chocolade, geschraagd door tannine van grote verfijning. De vaste en mooi ronde structuur geeft een lange afdronk prijs.'},
'mouton|2014':{taste:'De kleur is een diep rood met een purperen tint. De verfijnde en voorname neus geeft aroma’s van zeer rijp fruit prijs, aangenaam vermengd met subtiele tonen van specerijen en vanille. De fluweelachtige aanzet vult de mond met een rijp en zacht lichaam op zijdeachtige, vaste tannine die een satijnen textuur omhult, met een zweem mineraliteit. De zeer lange afdronk toont een harmonische verbinding van complexiteit, opulentie en frisheid.'},
'mouton|2015':{taste:'De wijn heeft een aantrekkelijke, diepe en donkere kleur met een purperen tint. De verfijnde en elegante neus geeft fruitige aroma’s van wilde braam en bosbes prijs. Tonen van toast, zoethout en lichte tabak komen daarna op en vullen een rijk en complex aromapalet aan. De frisse, volle en lichtjes zilte aanzet toont een grote intensiteit en opent op zachte en romige tannine die een zijdeachtige textuur omhult.'},
'mouton|2016':{taste:'De wijn is een donker en intens kersenrood. De zeer verfijnde neus geeft volmaakt rijp fruit prijs. Aroma’s van rijpe bosbes en cassis verbinden zich harmonieus met bloemige tonen. Bij beluchting ontvouwt de neus zich op peper en specerijen, in balans gehouden door elegante tonen van grafiet en lichte tabak, die charme en adeldom brengen in een uitgestrekt aromapalet. De volle en dichte aanzet toont uitzonderlijk ronde en zijdeachtige tannine.'},
'mouton|2017':{taste:'De wijn heeft een diepe, donkere kleur met een granaatrode tint. De elegante en complexe neus opent op aroma’s van wilde bessen. Bij beluchting brengen tonen van peper, cassisknop en gedroogde bloemen een bevredigend gevoel van harmonie. De aanzet is fris, scherp omlijnd en goed gestructureerd en leidt naar een dicht en vol midden van de mond op smaken van fris fruit. Verfijnde en rijpe tannine bekleedt het gehemelte.'},
'mouton|2018':{taste:'De wijn heeft een intense, diepzwarte kleur. De neus geeft intense aroma’s van rijp fruit en tonen van nootmuskaat prijs, afgezet tegen toetsen munt. De ruime, volle en verfijnde aanzet opent op smaken van braam en kers, opgetild door een zweem specerijen. Gulle, romige en mooi ronde tannine schraagt gekonfijte smaken en geeft een algehele indruk van weelde. Een groot evenwicht tussen het fruit en de tannine baant de weg.'},
'mouton|2019':{taste:'De wijn is een intens granaatrood met een purperen tint. Fris, zeer expressief en precies in de neus geeft hij aroma’s van braam, zwarte kers en zoethout prijs, met een lichtjes minerale inslag. Hij is zacht en opulent in de mond, met een aantrekkelijke zoetheid, en omhult voortreffelijk patricische, ronde en krachtige tannine. Over het geheel prachtig rijk mondt hij uit in een stijlvolle, weelderige en zeer harmonische afdronk.'},
'mouton|2020':{taste:'De wijn is een diep, donker, granaatgetint kersenrood. De verfijnde en complexe neus opent op opmerkelijk rijp zwart fruit en geeft bij beluchting aroma’s van cassis en anijs prijs, verbonden met toetsen vuursteen en een subtiele zweem sigarenkistje. Uit een zachte maar volle aanzet toont de mond zeer precieze tannine, die een harmonisch evenwicht vindt met de verfijning van mentholachtige en rokerige tonen.'},
'mouton|2021':{taste:'De wijn is diep en donker, met een glanzende purperen tint. De intense en elegante neus toont verleidelijk geparfumeerde aroma’s van braam en cassis, verbonden met bloemige tonen van iris en toetsen specerijen en cederhout. Een weelderige, sappige aanzet leidt naar een prachtig evenwichtige, frisse en harmonische mond, waarin smaken van bigarreaukers omhuld worden door een structuur van sappige, patricische tannine.'},
'mouton|2022':{taste:'Château Mouton Rothschild 2022 is zo lichtend als het jaar zelf was. Vanaf het begin intens geeft hij geconcentreerde aroma’s van fris, volledig rijp zwart fruit prijs, met tonen van cassis en braam die subtiel onderstreept worden door toetsen grafiet en cacaoboon. Een wijn van oneindige diepte: vol, gul en romig zacht, uiterst patricisch en van grote zuiverheid. Zwemen cederhout, specerijen en witte peper vullen het geheel aan.'},
'mouton|2023':{taste:'De wijn is een glinsterend, glanzend granaatrood met een karmozijnen tint. Verfijning en precisie zijn vanaf het begin merkbaar, met aroma’s van volledig rijpe braam. Discrete en aanvullende toetsen patisserie, snoepgoed en pure chocolade geven een harmonisch evenwicht tussen frisheid en opulentie. Zacht en vol geeft hij met zijn krachtige, stijlvolle en harmonieus geïntegreerde tannine een aantrekkelijke energie.'},
'olivier|2010':{note:'Ideaal zomerweer. Op een strenge winter in 2010 volgde een tamelijk schuchtere lente, wat voor een late start van de groei zorgde. Aromatische, rijke en gestructureerde wijnen: Château Olivier kon zo met het aromatische potentieel van elk ras spelen door geval per geval, perceel per perceel te oogsten.'},
'olivier|2012':{note:'Na een koude, droge winter, gevolgd door een vochtige, koele lente, kwam de bloei laat en verliep ze ongelijk. Er werd bijzonder veel werk in de wijnstokken gestopt, met een minutieuze groene oogst om alle trossen te verwijderen die achterop raakten in hun rijping.',taste:'De kleur is een mooi helder rood, de neus is zeer aromatisch met tonen van rood fruit, zoethout en specerijen. Alle rijpheid van de Cabernet Sauvignon laat zich in de mond voelen, met zijdeachtige tannine die zich verbindt met de rondheid van de Merlot. De mond is dicht. Een mooie fruitige lengte; deze wijn valt op door zijn evenwicht en zijn structuur.'},
'olivier|2013':{note:'Wat we van het weer in de eerste helft van 2013 zullen onthouden, zijn zes maanden regen en lage temperaturen, die de groeicyclus meer dan veertien dagen achterop brachten. De hete, zonnige zomer werd gestoord door enkele gewelddadige onweersbuien, die de wijngaard van Château Olivier spaarden.',taste:'De robe is een aantrekkelijk granaatrood. De neus is expressief, met aroma’s van fris fruit en cassis, samen met geroosterde en mokkatonen. De mond is vlezig en soepel, met aroma’s van goed uitgerijpt rood fruit. De tannine is gesmolten. Er is veel elegantie en een mooie rokerige lengte.'},
'olivier|2014':{note:'Na een zachte, regenachtige winter begon de groei vroeg. De véraison begon op 23 juli voor de Merlot, de Cabernet Sauvignon, de Sauvignon en de Sémillon.',taste:'De kleur is diep. De neus is fruitig, op tonen van gekonfijte kers, met enkele houtige aromatische retours. De aanzet is soepel, het midden van de mond vlezig, de afdronk lang en tannisch. De tannine is rond en rijp.'},
'olivier|2015':{note:'Bloei en vruchtzetting vonden plaats onder uitstekende omstandigheden. De rijping zette zich voort onder droog, warm weer tot aan de oogst, wat een goede concentratie bevorderde.',taste:'De neus is zeer expressief, met aroma’s van rijp rood fruit en kruidige tonen; het midden van de mond is fluweelachtig en vlezig, de tannine aanwezig en rijp. Een zeer mooie substantie, een evenwicht tussen aromatische rijpheid, finesse en elegantie, en een aanhoudende afdronk.'},
'olivier|2016':{note:'De winter was zacht en zeer nat. Bij de bloei ging een venster van goed weer open; die begon op 28 mei voor de Merlot en de Cabernet Sauvignon.',taste:'Het bouquet is intens van zwart fruit, en de houttoets is fijn en delicaat. Die volmaakt geïntegreerde frisheid werkt prachtig samen met de fijne, rijpe tannine en geeft een harmonisch geheel.'},
'olivier|2017':{note:'De tamelijk droge winter van 2017 ging een zachte lente vooraf. De vorst van 27 en 28 april spaarde Château Olivier niet.',taste:'De Merlots tonen zich fruitig en vlezig. De Cabernets Sauvignons konden werkelijk het beste maken van de zomerse omstandigheden van eind september, toen de temperaturen boven de 25 graden uitkwamen. De tannine biedt dichtheid en lengte.'},
'olivier|2018':{note:'Op de winter volgde een zachte, regenachtige lente. De bloei begon op 24 mei voor de Merlot en op 27 mei voor de Sémillon.',taste:'De kleur is een diep robijnrood. De neus is intens, met aroma’s van rijp rood fruit en van de haard, met enkele rokerige tonen. De mond is lang en dicht. De overvloedige tannine is zeer goed geïntegreerd. Een zeer grote wijn.'},
'olivier|2019':{window:'Het hoge gehalte aan glutathion, een natuurlijke antioxidant, laat een groot bewaarpotentieel verwachten.',note:'De véraison vond plaats op 25 juli voor onze witte rassen, op de 26e voor de Merlot en de Cabernet Sauvignon en op 5 augustus voor de Petit Verdot. Regen, zonder overdaad, bleef beperkt tot 22 tot 25 september.',taste:'De robe is dicht, ondoorzichtig, diep purper. De intense neus is open en fijn. Naast mentholachtige en kruidige tonen komt zwart fruit met een sterke rijpheid tot uitdrukking: een wijn van ras. De aanzet in de mond is zeer vlezig en wordt snel gekenmerkt door een opmerkelijke dichtheid.'},
'olivier|2020':{note:'Na een december die iets natter was dan gemiddeld, was de winter zacht, en februari in het bijzonder (3,5° boven het gemiddelde). De vroege uitloop van 17 maart maakte de periode met vorstrisico langer.',taste:'De wijn is precies en gul: goed uitgerijpt rood fruit, gesmolten en elegante tannine. Een rijke, smeuïge jaargang met een tannische structuur die een groot jaar waardig is.'},
'olivier|2021':{note:'Na een zachte, regenachtige winter was de uitloop gelijkmatig, regelmatig en vroeg, rond 21 maart. De lente als geheel was tamelijk koel (de gemiddelde temperatuur in mei lag 1,5 °C boven het tienjarig gemiddelde).',taste:'Een mooie purperen robe. In de neus vermengen mentholachtige aroma’s zich met zwart fruit (cassis, braam), die in de mond frisheid met smeuïgheid verbinden. De aanzet is helder, en de rondheid en het fruit van de Merlot geven hem een zekere gulheid. Dankzij de Cabernet Sauvignon en de Petit Verdot is het midden van de mond compact, met een aanhoudende en zeer verleidelijke afdronk.'},
'olivier|2022':{note:'Met een koude januari en een zachtere februari lagen de wintertemperaturen en -neerslag rond het gemiddelde. De bloei was dus vroeg en van goede kwaliteit: 17 mei voor de Cabernet Sauvignon en de Merlot, 20 mei voor onze witte rassen, Sauvignon en Sémillon, en 22 mei voor de Petit Verdot.'},
'olivier|2023':{note:'De wintertemperaturen en -neerslag lagen rond het gemiddelde, met een koudere februari, wat de groei vertraagde en het risico van voorjaarsvorst op afstand hield. Daarop volgde een zeer zachte lente met uitgesproken neerslag, zodat de meeldauwdruk aanzienlijk was.'},
'pontet-canet|2000':{note:'Na een halfhartig begin van de zomer, gevolgd door een bijzonder hete en droge augustus, konden we opnieuw het eeuwenoude gezegde bevestigen: ‘De most wordt in augustus gemaakt’.'},
'pontet-canet|2001':{note:'Na wat een zeer regenachtige winter leek, hadden de wijnstokken het voordeel van droog weer terwijl de bladeren zich openden en groeiden. Het bladerdek aan weerszijden van de druiventrossen terugbrengen geeft ons een volmaakte rijping, gevolgd door de zomersnoei, die bestaat uit het verfijnen van de stand van de trossen ten opzichte van elkaar.'},
'pontet-canet|2002':{note:'2002 onderscheidt zich door droge weersomstandigheden in de lente, gevolgd door een middelmatige zomer. De maand september, uitzonderlijk heet en droog, maakte daarentegen een opmerkelijke rijping mogelijk, die zeer goed tot volmaakt was voor de Cabernet Sauvignon.'},
'pontet-canet|2003':{note:'De jaargang 2003 zal ons altijd aan de hittegolf van die zomer herinneren. De bloei, die in de laatste veertien dagen van mei plaatsvond, wees erop dat de oogst rond 15 tot 20 september zou vallen.',taste:'Een heldere, lichtende robijnen tint. Een zonnige, gulle neus van donkere bessen, geplette aardbei en verbena met een zweem menthol. Ruim en energiek in de mond. Sappig en dynamisch geeft de jaargang fruitaroma’s prijs, gedragen door een elegante, mooi ronde textuur die het geheel zachtheid geeft. Een evenwichtige, nazinderende afdronk brengt de serene kracht van een uitzonderlijke jaargang tot uitdrukking.'},
'pontet-canet|2004':{note:'Een van de belangrijkste kenmerken van het jaar 2004 ligt in de grote droogte. Toch kwam er in de zomer wat onwelkome regen, die de bessen van een al ruime oogst verder deed zwellen.',taste:'Een heerlijk intense robijnen tint met purperen reflexen. De neus verleidt met tonen van aardbei, framboos en kers, opgewekt door de frisheid van rokerige chocolade en milde peper. Een fluweelachtige, poederige textuur in de mond geeft puur, precies fruit prijs, gedragen door elegante tannine. Een delicate afdronk zindert na met kruidige en rokerige nuances.'},
'pontet-canet|2005':{note:'De jaargang 2005 zal in het geheugen blijven als het jaar van de grote droogte. De oogst begon op 26 september voor de Merlots, met slechts één plukploeg, zodat de overige druiven over de verschillende terroirs het volmaakte rijpheidsniveau konden bereiken.',taste:'Een heldere, levendige karmijnen tint. Een diepe, intense neus van braam, cassis en een toets chocolade, onderstreept door een zweem menthol. Dicht en geconcentreerd in de mond, met vaste, precieze en volmaakt geïntegreerde tannine. Aanhoudende aroma’s van fruit en chocolade voor een lange, smaakvolle afdronk, in een uitdrukking van beheerste kracht en buitengewoon evenwicht.'},
'pontet-canet|2006':{note:'Na de regen van het einde van de winter kende de streek een aanhoudende periode van heet, droog weer. De bloei wees op een betrekkelijk vroege oogst, rond 20 tot 25 september.',taste:'Een lichtende robijnen tint. Een gulle, ruime neus verbindt cassis, aalbes en framboos met nuances van eucalyptus, tijm en lichtjes rokerige chocolade. In de mond zet een volle, levendige aanzet zich met energie door. Een sappig, expressief mondgevoel geeft aroma’s van rode bessen en cacao prijs, gedragen door gestructureerde, elegante tannine. Een lange, nazinderende afdronk met elegante tonen van ceder en een mooie aromatische spanning.'},
'pontet-canet|2007':{note:'Die omstandigheden maakten een lange bloeiperiode mogelijk, maar bevorderden ook de ziekten van de wijnstok. Gelukkig kwam in september het goede weer terug, wat een goede rijping toeliet.',taste:'Een robijnen tint, omzoomd door baksteenrode reflexen in een elegant patina. Een bloemige, rokerige neus, verrijkt met tonen van aalbes, ceder en chocolade. In de mond wordt een zijdeachtige, poederige textuur gedragen door delicate, milde tannine. Een precieze, subtiel kruidige afdronk houdt aan, gracieus en discreet.'},
'pontet-canet|2008':{note:'Maar de natuur besliste anders en bracht ons vier maanden regen en een gebrek aan zon in de zomer.',taste:'Een levendige, diepe karmijnen tint. Een opgewekte, gulle neus opent met tonen van bosaardbei en blauwe bosbes, opgewekt door aroma’s van eucalyptus en geurige kruiden en verrijkt door een elegante toets rook. In de mond wordt een ruime, krachtige, sappige, zilte textuur onderstreept door romige, mooi ronde tannine. Een lange, evenwichtige afdronk is dicht en fris, nazinderend en levendig.'},
'pontet-canet|2009':{note:'Dat was vooral in het begin van het seizoen nuttig, toen veelvuldige neerslag de herinnering aan de twee voorgaande jaren terugbracht. Toen kwam met de zomer de zon, die zich tot aan de oogst over de streek vestigde en al onze hoop voor de komende jaargang meebracht.',taste:'Een diepe, schitterende granaatrode tint. Een dichte, meeslepende neus van cassis, braam en grafiet met nuances van geurige kruiden en specerijen. Een intense, levendige fruitrijkdom. Een ruim, gestructureerd mondgevoel — krachtig en precies — wordt gedragen door fijn geslepen tannine. Een levendige, langgerekte afdronk houdt aan met een elegante frisheid.'},
'pontet-canet|2010':{note:'Daarna veroorzaakte onstabiel weer tijdens de bloei coulure, wat het aantal bessen verminderde, vooral in onze oudere Merlotpercelen. Toch overheersten zon en droogte tot aan de oogst, wat een mooie jaargang aankondigde.',taste:'Indrukwekkend in de mond, met een buitengewone dichtheid en schitterend fruit. Cassis en aardbei leveren een levendige frisheid, terwijl soepele maar besliste tannine een ruime, fijn geslepen structuur brengt.'},
'pontet-canet|2011':{note:'Het hete, droge weer bracht een lach op het gezicht van de wijnboeren: het hield ziekten op afstand en wekte de hoop op een vroege oogst, vaak een van de sleutels tot een zeer goede jaargang. De bloei vond bijzonder vroeg plaats, rond half mei, bij zeer droog weer, wat vaak schrale trossen en kleine bessen betekende.',taste:'Een schitterende granaatrode tint. Een verfijnde, elegante neus verbindt cassis en aalbes met bloemige en kruidige tonen. In de mond wordt een zijdeachtige, sappige textuur gedragen door fijne, volmaakt geïntegreerde tannine. Aroma’s van cassis, witte peper en ceder spelen met elkaar in een nette, strakke structuur. Een lange, zilte afdronk is schitterend.'},
'pontet-canet|2012':{note:'Na een bijzonder zachte winter zette zich in de lente regen in. Daardoor kwam de bloei tamelijk laat en duurde ze langer dan gewoonlijk.',taste:'Een lichtende, levendige karmijnen tint. Een complexe, expressieve neus geeft jamachtige cassis, anijs, eucalyptus en pure chocolade prijs. In de mond een ruime aanzet met een heerlijke spanning. Aroma’s van rijpe donkere bessen vlechten zich door balsemieke en chocoladeachtige tonen. Een evenwichtige wijn met een grote energie. Een lichtjes houtige afdronk levert een aanhoudende, schitterende frisheid.'},
'pontet-canet|2013':{note:'Een koude en vochtige lente begeleidde het eerste deel van de cyclus van de wijnstok. De bloei kwam daardoor laat, begin juni, bij bijzonder onbehulpzaam weer.',taste:'Een kristalheldere karmijnen tint. Een elegante, aromatische neus verbindt frisse kruiden, tijm, aalbes en kers met een toets specerijen die de elegantie van de jaargang onderstreept. In de mond zet een nette, poederige textuur puur, precies fruit in het licht. De lange, frisse afdronk is opmerkelijk elegant.'},
'pontet-canet|2014':{note:'Als het verhaal van de jaargang 2014 verteld moest worden, zou het beginnen met een bijzonder zachte en vochtige winter. De lente bracht het soort omstandigheden waar we meer aan gewend zijn.',taste:'Een levendige granaatrode tint. Een heldere, expressieve neus verbindt smakelijke rode bessen met de frisheid van menthol. Een precies, levendig bouquet met subtiele nuances van specerijen. In de mond is de wijn ruim en dynamisch, gedragen door vaste maar delicate, satijnzachte tannine. De afdronk zindert na met de kenmerkende intensiteit van een stoutmoedige, harmonische jaargang.'},
'pontet-canet|2015':{note:'De bloei begon langzaam omdat het weer niet warm genoeg was, maar versnelde snel toen de zon plotseling terugkwam. De weersomslag hield aan met twee maanden onafgebroken hitte en droogte, ongewoon voor de streek.',taste:'Een diepe, donkere granaatrode tint. Een bloemige, rageachtige neus verbindt geplette aardbei, cassis en grafiet met een zweem menthol. Intense, precieze aroma’s eisen de aandacht op. In de mond omhult een ruime, zijdeachtige textuur volmaakt milde tannine. Een prikkelende wijn met het fruit op de voorgrond en een lange, sappige afdronk die het evenwicht en de harmonie van een schitterende jaargang bevestigt.'},
'pontet-canet|2016':{note:'De winter was bijzonder zacht en nat en vulde de waterreserves overvloedig aan, wat de wijnstokken vele maanden actieve groei verzekerde. De bloei, die eind mei plaatsvond, was een zeer spannende tijd.',taste:'Evenwichtig in de mond, met tonen van zwarte kers, zoethout en andere donkere bessen. Een frisse, nazinderende afdronk is het kenmerk van deze diepe, precieze wijn.'},
'pontet-canet|2017':{note:'Al is neerslag een kenmerk geweest van de meeste recente Bordeaux-jaargangen die op een ‘7’ eindigen, 2017 werd gekenmerkt door vorst in een ijskoude nacht eind april. Daarna vestigde zich voor het grootste deel van het seizoen zeer gunstig weer voor de wijnstokken: de bloei vond half mei plaats en de bessen waren op 7 juli van kleur verschoten.',taste:'Een levendige granaatrode tint. Een elegante, expressieve neus verbindt scherpe rode bessen en chocolade met toetsen munt en eucalyptus. Elegant en precies is het aromatische palet fris en diep tegelijk. In de mond wordt een soepele, ruime textuur gedragen door delicate tannine. Een frisse, elegante afdronk zindert na met harmonie en gratie.'},
'pontet-canet|2018':{note:'Na een bijzonder natte winter met haast geen lage temperaturen en een bewolkte, zachte en over het geheel droge lente, begon de groeicyclus van de wijnstok begin april. De bloei vond eind mei plaats, begeleid door veelvuldige periodes van saai en treurig weer die tot in de tweede helft van juni aanhielden.',taste:'Een dichte, schitterende granaatrode tint. Een geconcentreerde, aromatische neus brengt cassis, eucalyptus en pure chocolade samen met milde specerijen en een zweem geroosterde koffie. Een krachtige, volle textuur in de mond wordt in balans gehouden door vaste, precieze tannine. Een lange, levendige afdronk is de uitdrukking van een prachtige intensiteit.'},
'pontet-canet|2019':{note:'Na een tamelijk zachte winter kwamen de eerste bladeren begin april aan de wijnstokken. Ondanks een zeer ongewone koudeprik in mei, die de groei van de ranken een paar dagen vertraagde, volgde de bloei zeer snel en gelijkmatig.',taste:'Een granaatrode tint met purperen reflexen. Een levendige, expressieve neus van aardbei, cassis en ceder, opgewekt door een toets rook en menthol. Een aromatische complexiteit geeft zich prijs met frisheid en intensiteit. In de mond is de jaargang ruim en fluweelachtig, met elegante tannine. Een lange afdronk zindert na in een harmonische, uiterst evenwichtige vlucht van fruit.'},
'pontet-canet|2020':{note:'Na een bijzonder zachte winter begon het groeiseizoen met opmerkelijk warme maanden maart en april. Het seizoen kende zijn eerste zware neerslag begin mei en daarna van 23 mei tot 20 juni, net na de bloei.',taste:'Een granaatrode tint met diep purperen reflexen. Een dichte, verfijnde neus met tonen van braam, cassis en ceder, voor een intense, precieze aromatische uitdrukking. Een sappige en satijnzachte textuur in de mond wordt onderstreept door soepele, aanwezige tannine. Een harmonische, verrukkelijke afdronk zindert na.'},
'pontet-canet|2021':{note:'Net als bij de bloei zagen we een gelijktijdigheid in het rijpen van de druivenrassen, een op zijn minst ongewoon fenomeen.',taste:'Een intense, lichtende purperen tint. Een delicate, elegante neus verbindt aardbei, cassis, hazelnoot en ceder in een bloemige, mentholachtige uitdrukking. In de mond wordt een romige, scherp omlijnde textuur onderstreept door strakke maar verfijnde tannine. Tonen van aalbes, gedroogde tijm en milde specerijen komen samen in een strak geweven, harmonische structuur. Een frisse, nette afdronk onderstreept de zuiverheid van de jaargang.'},
'pontet-canet|2022':{note:'De oogst vond dus zeer vroeg plaats, van 8 tot 28 september.',taste:'Purper, haast violet van tint. Een intense, geurige neus van cassis, ceder en eucalyptus, opgetild door een toets peper in een heldere, schitterende uitdrukking van aroma’s. In de mond is de wijn smaakvol, met een dichte, fluweelachtige textuur. Een strak geweven, elegante structuur vindt een evenwicht met de frisheid van menthol. De warme, nazinderende afdronk is aromatisch rijk en levendig.'},
'pontet-canet|2023':{note:'Na een koude maar betrekkelijk droge winter liet de zachte lente de wijnstokken prachtig gedijen. De bloei begon op 23 mei onder ideale weersomstandigheden, en de warme, droge maand juni wees op een zeer vroege oogst.',taste:'In de mond is de jaargang ruim en fluweelachtig, met tonen van ceder, cassis en aardbei. Een romige, harmonische textuur zindert na in een lange, levendige afdronk van bloemige tonen en frisheid, voor een meeslepende, volmaakte jaargang.'},
'prieure-lichine|2010':{note:'De gematigde waterstress, in combinatie met de afwisseling van koele nachten en warme, zonnige dagen, bevorderde de rijping van de druiven zonder schimmeldruk.'},
'prieure-lichine|2011':{note:'De warme, droge lente versnelde de groei van de wijnstok en de eerste bloemen verschenen al begin mei op de Merlots. Een gelijkmatige bloei liet een zeer vroege oogst (drie weken voorsprong) en gulle volumes verwachten.'},
'prieure-lichine|2012':{note:'2012 betekende een terugkeer naar normaal weer voor de streek van Bordeaux, met een natte, koele lente, gevolgd door een droge en redelijk warme zomer.'},
'prieure-lichine|2013':{note:'De winter van 2012-2013 was tamelijk zacht en gul met water, waardoor de bodems zich na vele jaren watertekort weer oplaadden. De tamelijk koele, natte lente verplichtte ons daarna tot de grootste waakzaamheid om onze wijngaard tegen de schimmeldruk staande te houden.'},
'prieure-lichine|2014':{note:'De bijzonder natte en zachte lente bracht een schimmeldruk die ons tot de grootste waakzaamheid verplichtte om onze wijngaard staande te houden. Eindelijk kwamen met september de zo lang verwachte zon en warmte: zes opeenvolgende weken droog, zacht weer brachten al onze percelen tot volle rijpheid en concentreerden sappige druiven.',taste:'De vergistingen verliepen rustig, met betrekkelijk lange maceraties op de kuipen van de grand vin (ongeveer 32 dagen), die rijpe, zeer fijne tannine prijsgaven en een precies, complex aromatisch profiel op bloemige, fruitige en kruidige tonen.'},
'prieure-lichine|2015':{note:'De lente gaf de wijnstok een gelijkmatige groei, met een aanzienlijke schimmeldruk door de zware neerslag van april en mei. De bessen groeiden weinig, en jonge wijnstokken toonden zorgwekkende tekenen van uitgesproken stress, wat ons verplichtte groen te oogsten voor het voortbestaan van de percelen.'},
'prieure-lichine|2016':{note:'De lente, binnen de tienjarige gemiddelden voor zowel temperatuur als neerslag, liet een gelijkmatige groei van de wijnstok toe, met daarbij een aanzienlijke schimmeldruk. Met een zeer droge juli en augustus (80% onder de normale neerslag) groeiden de druiven weinig en kwam de véraison traag op gang.'},
'prieure-lichine|2017':{note:'Na een koude winter, januari in het bijzonder, en met een watertekort, begon de groeicyclus op de gebruikelijke manier eind maart, met een gelijkmatige, snelle groei. Begin mei versnelden de zon en de weer milder geworden temperaturen het tempo, met de eerste bloemen tien dagen vóór een normaal seizoen.'},
'prieure-lichine|2018':{note:'De gulle neerslag van de winter en de lente verzekerde de wijnstok het hele seizoen door een waterreserve. De oogst verliep zonder onderbreking en liet ons elke sector in een onberispelijke gezondheidstoestand plukken.',taste:'Het onderstampen, door zijn fysieke werking die de sappen tijdens de alcoholische vergisting vrijmaakt, is een extra troef om rijpe en zijdeachtige tannine te onttrekken.'},
'prieure-lichine|2019':{note:'Gedragen door een tamelijk zachte, droge winter kondigde de jaargang 2019 zich eind maart aan met een klassieke uitloop van de wijnstok.'},
'prieure-lichine|2020':{note:'2020 draaide om drie sleutelfactoren die het profiel van de wijnen sterk hebben bepaald: een regenachtige lente, een zomer van grote droogte en een vroege cyclus. De winter, zeer nat in november, was bijzonder zacht in februari. De lente, vooral nat in april en begin mei, bracht een sterke meeldauwdruk, die de ploegen met kortere intervallen tussen de behandelingen in de hand probeerden te houden.'},
'prieure-lichine|2021':{note:'Na een jaargang 2020 die door de zomerdroogte was gekenmerkt, was de winter van 2020-2021 bijzonder nat en zacht, waardoor het grondwater zich weer oplaadde. De percelen die gewoonlijk laat zijn, waren al aan het groeien, wat het risico van een zware vorstperiode vergrootte.',taste:'De Cabernets Sauvignons zullen van dat water profiteren om nog hoekige tannine te verfijnen.'},
'prieure-lichine|2022':{window:'De assemblage, gedragen door onze Cabernets Sauvignons, bevestigt het bewaarpotentieel van deze jaargang, om bij het rijpen alle complexiteit van een Grand Cru te ontwikkelen.',note:'De jaargang 2022 zal de geschiedenis van de Bordeaux in veel opzichten kenmerken: een nooit eerder gezien aantal hittegolven, gecombineerd met geringe neerslag, geeft wijnen van een buitengewoon profiel, diep van kleur en zijdeachtig in de mond.',taste:'Met het onderstampen optimaliseren we het contact tussen de schillen en het sap en kunnen we zo rijpe en zijdeachtige tannine onttrekken.'},
'prieure-lichine|2023':{note:'De zachtheid van de winter van 2022-2023 gaf ons een vredig begin van het seizoen. Deze kapriciuze en veeleisende jaargang kwam uiteindelijk tot bedaren onder de grote hitte van de zomer, wat een gelijkmatige véraison toeliet en daarna rijpe, evenwichtige bessen prijsgaf.'},
'smith-haut-lafitte|2015':{window:'Vriendelijkheid en verleidingskracht. Te drinken vanaf 2018.',note:'2015 werd gekenmerkt door een lange droogte van maart tot juli, en daarna een tamelijk koele en natte augustus, wat een optimale rijpheid bracht terwijl een goede frisheid bewaard bleef. Het vroege opkomen van de waterstress zette de wijnstok aan tot een grote tannineproductie en gaf die tannine ook de tijd om volmaakt te rijpen.'},
};
